def fnv(s, fnv1=False):
    h=2166136261
    for b in s.encode():
        if fnv1:
            h=(h*16777619)&0xffffffff; h ^= b
        else:
            h ^= b; h=(h*16777619)&0xffffffff
    return h
cases=[(("love","</s>"),685),(("love","love"),405),(("unknown","</s>"),349)]
for fnv1 in [False,True]:
 for overflow in [32,64,None]:
  for mult in [116049371,16777619,16777651,31,33,131,1000003,100000007]:
    outs=[]
    for words,X in cases:
        h1,h2=[fnv(w,fnv1) for w in words]
        h=h1*mult+h2
        if overflow==32: h&=0xffffffff
        elif overflow==64: h&=0xffffffffffffffff
        outs.append(17+h%1000)
    if outs==[c[1] for c in cases]: print("MATCH",fnv1,overflow,mult)
    # print some for main mult
  print("fnv1",fnv1,"overflow",overflow,"mult main",[(17+ (((fnv(c[0][0],fnv1)*116049371+fnv(c[0][1],fnv1)) & (0xffffffff if overflow==32 else 0xffffffffffffffff if overflow==64 else (1<<128)-1))%1000)) for c in cases])
PY"}

