def fnv(s):
    h=2166136261
    for b in s.encode():
        h ^= b; h=(h*16777619)&0xffffffff
    return h
data=[(("love","</s>"),309),(("good","</s>"),818),(("hate","</s>"),337),(("love","good"),948),(("good","love"),682),(("love","love"),173),(("hate","bad"),112),(("good","hate"),958),(("unknown","</s>"),941),(("xyz","</s>"),778)]
for (a,b),idx in data:
    r=idx-17
    print(a,b,"r",r,"h1low",fnv(a)&1023,"h2low",fnv(b)&1023,"diff",(r-(fnv(b)&1023))%1024)
candidates=[]
for C in range(2000000):
    ok=True
    for (a,b),idx in data:
        if ( ((fnv(a)&1023)*(C&1023)+(fnv(b)&1023))%1024) != idx-17: ok=False;break
    if ok: candidates.append(C)
print("candidate C low residues up to",candidates[:20])
# C modulo 1024 residues
res=[]
for C in range(1024):
    if all(((fnv(a)&1023)*C+(fnv(b)&1023))%1024==idx-17 for (a,b),idx in data): res.append(C)
print("residues mod1024",res)
# also test formula h = h1; h = h XOR (?) etc, or h = (h1*C XOR h2)
res2=[]
for C in range(1024):
    if all((((fnv(a)&1023)*C) ^ (fnv(b)&1023))==idx-17 for (a,b),idx in data): res2.append(C)
print("xor residues",res2)
# maybe token hash used in addWordNgrams is not fnv(word) but something: hashes are from Dictionary::hash which returns uint32 but maybe then ??? Check relation r for eos pairs: r as function of h1 alone (h2 constant) 
