import struct
words=['</s>','love','good','hate','wonderful','sad','horrible','poor','best','worst','fantastic','bad','happy','terrible','great','awful','excellent']
def fnv(s):
 h=2166136261
 for b in s.encode(): h=((h^b)*16777619)&0xffffffff
 return h
def ngrams(w):
 if w=='</s>': return []
 s='<'+w+'>'; out=[]
 for i in range(len(s)):
  cur=''
  for j in range(i,min(len(s),i+6)):
   cur+=s[j]
   if len(cur)>=3 and not (len(cur)==1 and (i==0 or j==len(s)-1)): out.append(cur)
 return out
buckets=set(); counts={}
for w in words:
 for ng in ngrams(w):
  b=fnv(ng)%10000; buckets.add(b); counts[b]=counts.get(b,0)+1
print("distinct subword buckets",len(buckets))
# load prune keys
def keys(path):
    d=open(path,"rb").read(); off=0
    def rd(fmt):
        nonlocal off; s=struct.calcsize(fmt); v=struct.unpack_from(fmt,d,off)[0]; off+=s; return v
    rd("<i");rd("<i"); [rd("<i") for _ in range(12)]; rd("<d")
    size=rd("<i"); rd("<i"); rd("<i"); rd("<q"); psz=rd("<q")
    for i in range(size):
        end=d.index(b"\x00",off); off=end+1; rd("<q"); rd("<b")
    return [(rd("<i"),rd("<i")) for _ in range(psz)]
