import subprocess,struct,math
# craft supervised model: use sup model with input rows simple and output rows simple so hidden for "love (no newline EOS? use newline includes EOS)" 
# load craft1 (wordng1, input row idx encoding dim0=i,dim1=1 other0; output from epoch0 zero originally in craft? craft.bin output zero? It was epoch0 supervised output zero)
# Instead modify a fresh parse generic from craft1.bin: locate input/output by traversing.
def load(path):
    d=bytearray(open(path,"rb").read()); off=0
    def rd(fmt):
        nonlocal off; s=struct.calcsize(fmt); v=struct.unpack_from(fmt,d,off)[0]; off+=s; return v
    rd("<i");rd("<i"); args_off=off; args=[rd("<i") for _ in range(12)]; rd("<d")
    size=rd("<i"); nw=rd("<i"); nl=rd("<i"); rd("<q"); prune=rd("<q")
    for i in range(size):
        end=d.index(b"\x00",off); off=end+1; rd("<q"); rd("<b")
    quant_off=off; q=rd("<b"); m=rd("<q"); n=rd("<q"); in_off=off; off+=m*n*4
    qout_off=off; qo=rd("<b"); mo=rd("<q"); no=rd("<q"); out_off=off
    return d, {"args":args,"nw":nw,"nl":nl,"in_off":in_off,"m":m,"n":n,"out_off":out_off,"mo":mo,"no":no,"args_off":args_off}
d,info=load("/tmp/t/craft1.bin"); print(info)
# set input all zero except love id1 dim0=1, EOS dim0=0 ( sentence love\n hidden avg dim0=0.5)
for i in range(info["m"]*info["n"]): struct.pack_into("<f",d,info["in_off"]+4*i,0.0)
struct.pack_into("<f",d,info["in_off"]+4*(1*10+0),1.0)
# output labels: row0 neg dim0 = x (variable), row1 pos dim0=0. Set x scale via loop in files for each desired logit: hidden .5, output neg = 2*logit
def test(loss_enum, logit):
    dd=bytearray(d)
    struct.pack_into("<i",dd,info["args_off"]+4*6,loss_enum) # args ints list offset? args_off at dim; indexes dim0 ws1 epoch2 minc3 neg4 wordng5 loss6 model7
    for i in range(info["mo"]*info["no"]): struct.pack_into("<f",dd,info["out_off"]+4*i,0.0)
    struct.pack_into("<f",dd,info["out_off"]+4*(0*10+0),2*logit)
    open("/tmp/t/prob.bin","wb").write(dd)
    r=subprocess.run(["./executable","predict-prob","/tmp/t/prob.bin","-","2"],input="love\n",capture_output=True,text=True)
    print(f"loss={loss_enum} logit={logit} rc={r.returncode} out={r.stdout.strip()} err={r.stderr[:100]} exact_sigmoid={1/(1+math.exp(-logit)) if abs(logit)<20 else (1 if logit>0 else 0)} softmax_neg={math.exp(logit)/(math.exp(logit)+1) if abs(logit)<20 else logit}")
for loss in [3,4,2,1]:
    for logit in [-10,-8,-2,0,0.123456,1,5,8,10,20]:
        test(loss,logit)
PY"}

