  uint32_t h = 2166136261u;
  for (size_t i = 0; i < s.size(); i++) {
    h = h ^ static_cast<uint32_t>(static_cast<unsigned char>(s[i]));
    h = h * 16777619u;
  }
  return h;
}

enum class model_name : int { cbow = 1, sg = 2, sup = 3 };
enum class loss_name : int { hs = 1, ns = 2, softmax = 3, onevsall = 4 };
enum class entry_type : int8_t { word = 0, label = 1 };

static std::string modelName(model_name m) {
  switch (m) {
    case model_name::cbow: return "cbow";
