}
static std::string lossName(loss_name l) {
  switch (l) {
    case loss_name::hs: return "hs";
    case loss_name::ns: return "ns";
    case loss_name::softmax: return "softmax";
    case loss_name::onevsall: return "one-vs-all";
    default: throw std::runtime_error("Unknown loss");
  }
}

// ------------------------------ Args ------------------------------

struct Args {
  std::string input;
  std::string output;
  double lr = 0.05;
  int32_t lrUpdateRate = 100;
  int32_t dim = 100;
  int32_t ws = 5;
  int32_t epoch = 5;
  int32_t minCount = 5;
  int32_t minCountLabel = 0;
  int32_t neg = 5;
  int32_t wordNgrams = 1;
  loss_name loss = loss_name::ns;
  model_name model = model_name::sg;
  int32_t bucket = 2000000;
  int32_t minn = 3;
  int32_t maxn = 6;
  int32_t thread = 12;
  double t = 1e-4;
  std::string label = "__label__";
  int32_t verbose = 2;
  std::string pretrainedVectors;
  bool saveOutput = false;
  int32_t seed = 0;

  int32_t cutoff = 0;
  bool retrain = false;
  bool qnorm = false;
  bool qout = false;
  int32_t dsub = 2;

  std::string autotuneValidationFile;
  std::string autotuneMetric = "f1";
  int32_t autotunePredictions = 1;
  int32_t autotuneDuration = 300;
  std::string autotuneModelSize;

  // Names of arguments explicitly present on the command line
  // (used by autotune warnings).
  std::set<std::string> manuallySet;

  void printHelp() const {
    std::cerr
        << "\nThe following arguments are mandatory:" << std::endl
        << "  -input              training file path" << std::endl
        << "  -output             output file path" << std::endl
        << "\nThe following arguments are optional:" << std::endl
        << "  -verbose            verbosity level [" << verbose << "]"
        << std::endl
        << "\nThe following arguments for the dictionary are optional:"
        << std::endl
        << "  -minCount           minimal number of word occurences ["
        << minCount << "]" << std::endl
        << "  -minCountLabel      minimal number of label occurences ["
        << minCountLabel << "]" << std::endl
        << "  -wordNgrams         max length of word ngram [" << wordNgrams
        << "]" << std::endl
        << "  -bucket             number of buckets [" << bucket << "]"
        << std::endl
        << "  -minn               min length of char ngram [" << minn << "]"
        << std::endl
        << "  -maxn               max length of char ngram [" << maxn << "]"
        << std::endl
        << "  -t                  sampling threshold [" << t << "]"
        << std::endl
        << "  -label              labels prefix [" << label << "]"
        << std::endl
        << "\nThe following arguments for training are optional:" << std::endl
        << "  -lr                 learning rate [" << lr << "]" << std::endl
        << "  -lrUpdateRate       change the rate of updates for the "
           "learning rate ["
        << lrUpdateRate << "]" << std::endl
        << "  -dim                size of word vectors [" << dim << "]"
        << std::endl
        << "  -ws                 size of the context window [" << ws << "]"
        << std::endl
        << "  -epoch              number of epochs [" << epoch << "]"
        << std::endl
        << "  -neg                number of negatives sampled [" << neg << "]"
        << std::endl
        << "  -loss               loss function {ns, hs, softmax, one-vs-all} ["
        << lossName(loss) << "]" << std::endl
        << "  -thread             number of threads (set to 1 to ensure "
           "reproducible results) ["
        << thread << "]" << std::endl
        << "  -pretrainedVectors  pretrained word vectors for supervised "
           "learning ["
        << pretrainedVectors << "]" << std::endl
        << "  -saveOutput         whether output params should be saved ["
        << (saveOutput ? "true" : "false") << "]" << std::endl
        << "  -seed               random generator seed  [" << seed << "]"
        << std::endl
        << "\nThe following arguments are for autotune:" << std::endl
        << "  -autotune-validation            validation file to be used "
           "for evaluation"
        << std::endl
        << "  -autotune-metric                metric objective {f1, "
           "f1:labelname} ["
        << autotuneMetric << "]" << std::endl
        << "  -autotune-predictions           number of predictions used for "
           "evaluation  ["
        << autotunePredictions << "]" << std::endl
        << "  -autotune-duration              maximum duration in seconds ["
        << autotuneDuration << "]" << std::endl
        << "  -autotune-modelsize             constraint model file size ["
        << autotuneModelSize << "] (empty = do not quantize)" << std::endl
        << "\nThe following arguments for quantization are optional:"
        << std::endl
        << "  -cutoff             number of words and ngrams to retain ["
        << cutoff << "]" << std::endl
        << "  -retrain            whether embeddings are finetuned if a "
           "cutoff is applied ["
        << (retrain ? "true" : "false") << "]" << std::endl
        << "  -qnorm              whether the norm is quantized separately ["
        << (qnorm ? "true" : "false") << "]" << std::endl
        << "  -qout               whether the classifier is quantized ["
        << (qout ? "true" : "false") << "]" << std::endl
        << "  -dsub               size of each sub-vector [" << dsub << "]"
        << std::endl;
  }

  void save(std::ostream& out) const {
    out.write((char*)&dim, sizeof(dim));
    out.write((char*)&ws, sizeof(ws));
    out.write((char*)&epoch, sizeof(epoch));
    out.write((char*)&minCount, sizeof(minCount));
    out.write((char*)&neg, sizeof(neg));
    out.write((char*)&wordNgrams, sizeof(wordNgrams));
    int32_t lv = static_cast<int32_t>(loss);
    int32_t mv = static_cast<int32_t>(model);
    out.write((char*)&lv, sizeof(lv));
    out.write((char*)&mv, sizeof(mv));
    out.write((char*)&bucket, sizeof(bucket));
    out.write((char*)&minn, sizeof(minn));
    out.write((char*)&maxn, sizeof(maxn));
    out.write((char*)&lrUpdateRate, sizeof(lrUpdateRate));
    double tt = t;
    out.write((char*)&tt, sizeof(tt));
  }
  void load(std::istream& in) {
    in.read((char*)&dim, sizeof(dim));
    in.read((char*)&ws, sizeof(ws));
    in.read((char*)&epoch, sizeof(epoch));
    in.read((char*)&minCount, sizeof(minCount));
    in.read((char*)&neg, sizeof(neg));
    in.read((char*)&wordNgrams, sizeof(wordNgrams));
    int32_t lv = 0, mv = 0;
    in.read((char*)&lv, sizeof(lv));
    loss = static_cast<loss_name>(lv);
    in.read((char*)&mv, sizeof(mv));
    model = static_cast<model_name>(mv);
    in.read((char*)&bucket, sizeof(bucket));
    in.read((char*)&minn, sizeof(minn));
    in.read((char*)&maxn, sizeof(maxn));
    in.read((char*)&lrUpdateRate, sizeof(lrUpdateRate));
    double tt = 0;
    in.read((char*)&tt, sizeof(tt));
    t = tt;
  }
  void dump(std::ostream& out) const {
    out << "dim" << " " << dim << std::endl;
    out << "ws" << " " << ws << std::endl;
    out << "epoch" << " " << epoch << std::endl;
    out << "minCount" << " " << minCount << std::endl;
    out << "neg" << " " << neg << std::endl;
    out << "wordNgrams" << " " << wordNgrams << std::endl;
    out << "loss" << " " << lossName(loss) << std::endl;
    out << "model" << " " << modelName(model) << std::endl;
    out << "bucket" << " " << bucket << std::endl;
    out << "minn" << " " << minn << std::endl;
    out << "maxn" << " " << maxn << std::endl;
    out << "lrUpdateRate" << " " << lrUpdateRate << std::endl;
    out << "t" << " " << t << std::endl;
  }

  // metricName/label parsed out of autotuneMetric; validates like reference
  void validateAutotuneMetric() const {
    const std::string& m = autotuneMetric;
    if (m == "f1") return;
    if (m.rfind("f1:", 0) == 0) {
      if (m.size() <= 3) {
        throw std::runtime_error("Empty metric label : " + m);
      }
      return;
    }
    throw std::runtime_error("Unknown metric : " + m);
  }
  std::string autotuneMetricLabel() const {
    if (autotuneMetric.rfind("f1:", 0) == 0) return autotuneMetric.substr(3);
    return "";
  }

  void parseArgs(const std::vector<std::string>& args) {
    // args[0] is command name
    std::string command = args.empty() ? "" : args[0];
    if (command == "supervised") {
      model = model_name::sup;
      loss = loss_name::softmax;
      minCount = 1;
      minn = 0;
      maxn = 0;
      lr = 0.1;
    } else if (command == "cbow") {
      model = model_name::cbow;
    } else if (command == "skipgram") {
      model = model_name::sg;
    }
    auto die = [&](const std::string& msg) -> void {
      std::cerr << msg << std::endl;
      printHelp();
      std::exit(EXIT_FAILURE);
    };
    for (size_t ai = 1; ai < args.size(); ai++) {
      std::string arg = args[ai];
      if (arg.empty() || arg[0] != '-') {
        std::cerr << "Provided argument without a dash! Usage:" << std::endl;
        printHelp();
        std::exit(EXIT_FAILURE);
      }
      manuallySet.insert(arg);
      auto need = [&](const std::string& name) -> std::string {
        if (ai + 1 >= args.size()) {
          std::cerr << name << " is missing an argument" << std::endl;
          printHelp();
          std::exit(EXIT_FAILURE);
        }
        return args[++ai];
      };
      if (arg == "-input") {
        input = need(arg);
      } else if (arg == "-output") {
        output = need(arg);
      } else if (arg == "-lr") {
        lr = std::stof(need(arg));
      } else if (arg == "-lrUpdateRate") {
        lrUpdateRate = std::stoi(need(arg));
      } else if (arg == "-dim") {
        dim = std::stoi(need(arg));
      } else if (arg == "-ws") {
        ws = std::stoi(need(arg));
      } else if (arg == "-epoch") {
        epoch = std::stoi(need(arg));
      } else if (arg == "-minCount") {
        minCount = std::stoi(need(arg));
      } else if (arg == "-minCountLabel") {
        minCountLabel = std::stoi(need(arg));
      } else if (arg == "-neg") {
        neg = std::stoi(need(arg));
      } else if (arg == "-wordNgrams") {
        wordNgrams = std::stoi(need(arg));
      } else if (arg == "-loss") {
        std::string v = need(arg);
        if (v == "hs") loss = loss_name::hs;
        else if (v == "ns") loss = loss_name::ns;
        else if (v == "softmax") loss = loss_name::softmax;
        else if (v == "one-vs-all") loss = loss_name::onevsall;
        else {
          std::cerr << "Unknown loss: " << v << std::endl;
          printHelp();
          std::exit(EXIT_FAILURE);
        }
      } else if (arg == "-bucket") {
        bucket = std::stoi(need(arg));
      } else if (arg == "-minn") {
        minn = std::stoi(need(arg));
      } else if (arg == "-maxn") {
        maxn = std::stoi(need(arg));
      } else if (arg == "-thread") {
        thread = std::stoi(need(arg));
      } else if (arg == "-t") {
        t = std::stof(need(arg));
      } else if (arg == "-label") {
        label = need(arg);
      } else if (arg == "-verbose") {
        verbose = std::stoi(need(arg));
      } else if (arg == "-pretrainedVectors") {
        pretrainedVectors = need(arg);
      } else if (arg == "-saveOutput") {
        saveOutput = true;
      } else if (arg == "-cutoff") {
        cutoff = std::stoi(need(arg));
      } else if (arg == "-retrain") {
        retrain = true;
      } else if (arg == "-qout") {
        qout = true;
      } else if (arg == "-qnorm") {
        qnorm = true;
      } else if (arg == "-dsub") {
        dsub = std::stoi(need(arg));
      } else if (arg == "-seed") {
        seed = std::stoi(need(arg));
      } else if (arg == "-autotune-validation") {
        autotuneValidationFile = need(arg);
      } else if (arg == "-autotune-metric") {
        autotuneMetric = need(arg);
      } else if (arg == "-autotune-predictions") {
        autotunePredictions = std::stoi(need(arg));
      } else if (arg == "-autotune-duration") {
        autotuneDuration = std::stoi(need(arg));
      } else if (arg == "-autotune-modelsize") {
        autotuneModelSize = need(arg);
      } else {
        std::cerr << "Unknown argument: " << arg << std::endl;
        printHelp();
        std::exit(EXIT_FAILURE);
      }
    }
    validateAutotuneMetric();
    if (input.empty() || output.empty()) {
      std::cerr << "Empty input or output path." << std::endl;
      printHelp();
      std::exit(EXIT_FAILURE);
    }
  }
};

