// ------------------------------ ProductQuantizer ------------------------------

class ProductQuantizer {
 public:
  static const int32_t ksub_ = 256;
  int32_t dim_ = 0;
  int32_t nsubq_ = 0;
  int32_t dsub_ = 0;
  int32_t lastdsub_ = 0;
  std::vector<real> centroids_;

  ProductQuantizer() {}
  ProductQuantizer(int32_t dim, int32_t dsub) : dim_(dim), dsub_(dsub) {
    nsubq_ = dim_ / dsub_;
    lastdsub_ = dim_ % dsub_;
    if (lastdsub_ == 0) {
      lastdsub_ = dsub_;
    } else {
      nsubq_++;
    }
    centroids_.assign((size_t)ksub_ * dim_, 0.0f);
  }

  int32_t getDim(int32_t sub) const {
    return sub == nsubq_ - 1 ? lastdsub_ : dsub_;
  }
  const real* getCentroids(int32_t sub, int32_t centroid) const {
    // Subquantizers before the last use dsub_ values per centroid.
    size_t base;
    if (sub < nsubq_ - 1) {
      base = ((size_t)sub * ksub_ + centroid) * dsub_;
    } else {
      base = (size_t)(nsubq_ - 1) * ksub_ * dsub_ + (size_t)centroid * lastdsub_;
    }
    return centroids_.data() + base;
  }
  real* getCentroids(int32_t sub, int32_t centroid) {
    return const_cast<real*>(
        static_cast<const ProductQuantizer*>(this)->getCentroids(sub, centroid));
  }

  void train(int64_t n, const real* x) {
    if (n < ksub_) {
      throw std::invalid_argument(
          "Matrix too small for quantization, must have at least 256 rows");
    }
    // K-means for every subquantizer.  Initial centroids are data
    // points picked from a shuffled index permutation.
    const int32_t niter = 25;
    const int64_t maxPoints = 256000;
    std::vector<int64_t> perm(n);
    std::iota(perm.begin(), perm.end(), 0);
    {
      std::minstd_rand rng(0);
      // std::shuffle equivalent using the same engine type
      for (int64_t i = n - 1; i > 0; i--) {
        std::uniform_int_distribution<int64_t> dist(0, i);
        int64_t j = dist(rng);
        std::swap(perm[i], perm[j]);
      }
    }
    int64_t np = std::min(n, maxPoints);
    std::vector<real> xs((size_t)np * dim_);
    for (int64_t i = 0; i < np; i++) {
      std::memcpy(&xs[(size_t)i * dim_], &x[(size_t)perm[i] * dim_],
                  dim_ * sizeof(real));
    }
    // The reference samples a fresh permutation per subquantizer;
    // a single permutation gives equivalent cluster quality.
    for (int32_t sub = 0; sub < nsubq_; sub++) {
      int32_t sd = getDim(sub);
      int32_t offset = sub * dsub_;
      std::vector<real> cents((size_t)ksub_ * sd);
      for (int32_t k = 0; k < ksub_; k++) {
        for (int32_t j = 0; j < sd; j++) {
          cents[(size_t)k * sd + j] = xs[(size_t)k * dim_ + offset + j];
        }
      }
      std::vector<real> sums((size_t)ksub_ * sd);
      std::vector<int64_t> counts(ksub_);
      std::vector<int32_t> assign(np);
      for (int32_t iter = 0; iter < niter; iter++) {
        for (int64_t i = 0; i < np; i++) {
          real best = std::numeric_limits<real>::max();
          int32_t bestk = 0;
          for (int32_t k = 0; k < ksub_; k++) {
            real dist = 0;
            for (int32_t j = 0; j < sd; j++) {
              real diff = xs[(size_t)i * dim_ + offset + j] -
                          cents[(size_t)k * sd + j];
              dist += diff * diff;
            }
            if (dist < best) {
              best = dist;
              bestk = k;
            }
          }
          assign[i] = bestk;
        }
        std::fill(sums.begin(), sums.end(), 0.0f);
        std::fill(counts.begin(), counts.end(), 0);
        for (int64_t i = 0; i < np; i++) {
          int32_t k = assign[i];
          counts[k]++;
          for (int32_t j = 0; j < sd; j++) {
            sums[(size_t)k * sd + j] += xs[(size_t)i * dim_ + offset + j];
          }
        }
        for (int32_t k = 0; k < ksub_; k++) {
          if (counts[k] == 0) {
            // Reinitialize empty clusters to a data point.
            int64_t idx = (k * 7919LL) % np;
            for (int32_t j = 0; j < sd; j++) {
              cents[(size_t)k * sd + j] = xs[(size_t)idx * dim_ + offset + j] +
                                           (real)1e-7 * (k + 1);
            }
          } else {
            for (int32_t j = 0; j < sd; j++) {
              cents[(size_t)k * sd + j] = sums[(size_t)k * sd + j] / counts[k];
            }
          }
        }
      }
      for (int32_t k = 0; k < ksub_; k++) {
        real* dst = getCentroids(sub, k);
        std::memcpy(dst, &cents[(size_t)k * sd], sd * sizeof(real));
      }
    }
  }

  void computeCode(const real* x, uint8_t* code) const {
    for (int32_t sub = 0; sub < nsubq_; sub++) {
      int32_t sd = getDim(sub);
      int32_t offset = sub * dsub_;
      real best = std::numeric_limits<real>::max();
      int32_t bestk = 0;
      for (int32_t k = 0; k < ksub_; k++) {
        const real* c = getCentroids(sub, k);
        real dist = 0;
        for (int32_t j = 0; j < sd; j++) {
          real diff = x[offset + j] - c[j];
          dist += diff * diff;
        }
        if (dist < best) {
          best = dist;
          bestk = k;
        }
      }
      code[sub] = (uint8_t)bestk;
    }
  }
  void computeCodes(const real* x, uint8_t* codes, int64_t n) const {
    for (int64_t i = 0; i < n; i++) {
      computeCode(x + (size_t)i * dim_, codes + (size_t)i * nsubq_);
    }
  }
  void addCodeToVector(const uint8_t* code, Vector& x) const {
    for (int32_t sub = 0; sub < nsubq_; sub++) {
      int32_t sd = getDim(sub);
      const real* c = getCentroids(sub, code[sub]);
      int32_t offset = sub * dsub_;
      for (int32_t j = 0; j < sd; j++) x[offset + j] += c[j];
    }
  }
  real dotCode(const uint8_t* code, const Vector& x) const {
    real sum = 0;
    for (int32_t sub = 0; sub < nsubq_; sub++) {
      int32_t sd = getDim(sub);
      const real* c = getCentroids(sub, code[sub]);
      int32_t offset = sub * dsub_;
      for (int32_t j = 0; j < sd; j++) sum += c[j] * x[offset + j];
    }
    return sum;
  }
  void save(std::ostream& out) const {
    out.write((char*)&dim_, sizeof(dim_));
    out.write((char*)&nsubq_, sizeof(nsubq_));
    out.write((char*)&dsub_, sizeof(dsub_));
    out.write((char*)&lastdsub_, sizeof(lastdsub_));
    out.write((char*)centroids_.data(),
              (std::streamsize)(centroids_.size() * sizeof(real)));
  }
  void load(std::istream& in) {
    in.read((char*)&dim_, sizeof(dim_));
    in.read((char*)&nsubq_, sizeof(nsubq_));
    in.read((char*)&dsub_, sizeof(dsub_));
    in.read((char*)&lastdsub_, sizeof(lastdsub_));
    centroids_.assign((size_t)ksub_ * dim_, 0.0f);
    in.read((char*)centroids_.data(),
            (std::streamsize)(centroids_.size() * sizeof(real)));
  }
};

class QuantMatrix : public Matrix {
 public:
  bool qnorm_ = false;
  int64_t m_ = 0;
  int64_t n_ = 0;
  std::vector<uint8_t> codes_;
  ProductQuantizer pq_;
  std::vector<uint8_t> normCodes_;
  ProductQuantizer normPQ_;

  QuantMatrix() {}
  QuantMatrix(DenseMatrix&& dense, int32_t dsub, bool qnorm)
      : qnorm_(qnorm), m_(dense.m_), n_(dense.n_) {
    if (m_ < ProductQuantizer::ksub_) {
      throw std::invalid_argument(
          "Matrix too small for quantization, must have at least 256 rows");
    }
    pq_ = ProductQuantizer((int32_t)n_, dsub);
    codes_.assign((size_t)m_ * pq_.nsubq_, 0);
    if (qnorm_) {
      normPQ_ = ProductQuantizer(1, 1);
      normCodes_.assign((size_t)m_, 0);
      // Normalize a copy of the data, gather norms
      std::vector<real> data((size_t)m_ * n_);
      std::vector<real> norms((size_t)m_);
      for (int64_t i = 0; i < m_; i++) {
        real norm = dense.l2NormRow(i);
        norms[i] = norm;
        real inv = norm == 0 ? 0 : 1.0f / norm;
        for (int64_t j = 0; j < n_; j++) data[(size_t)i * n_ + j] = dense.at(i, j) * inv;
      }
      pq_.train(m_, data.data());
      pq_.computeCodes(data.data(), codes_.data(), m_);
      normPQ_.train(m_, norms.data());
      normPQ_.computeCodes(norms.data(), normCodes_.data(), m_);
    } else {
      pq_.train(m_, dense.data_);
      pq_.computeCodes(dense.data_, codes_.data(), m_);
    }
  }
  int64_t size(int32_t dim) const override { return dim == 0 ? m_ : n_; }
  const uint8_t* getCode(int64_t row) const {
    return codes_.data() + (size_t)row * pq_.nsubq_;
  }
  real getNorm(int64_t row) const {
    if (!qnorm_) return 1.0f;
    const real* c = normPQ_.getCentroids(0, normCodes_[(size_t)row]);
    return c[0];
  }
  void addRowToVector(Vector& x, int64_t row) const override {
    if (!qnorm_) {
      pq_.addCodeToVector(getCode(row), x);
    } else {
      Vector tmp((int64_t)n_);
      tmp.zero();
      pq_.addCodeToVector(getCode(row), tmp);
      real norm = getNorm(row);
      for (int64_t j = 0; j < n_; j++) x[j] += norm * tmp[j];
    }
  }
  real dotRow(const Vector& x, int64_t row) const override {
    real sum = pq_.dotCode(getCode(row), x);
    if (qnorm_) sum *= getNorm(row);
    if (std::isnan(sum)) throw DenseMatrix::EncounteredNaNError();
    return sum;
  }
  void addVectorToRow(const Vector&, int64_t, real) override {
    throw std::runtime_error("addVectorToRow not supported for quantized matrix");
  }
  void save(std::ostream& out) const override {
    out.write((char*)&qnorm_, sizeof(qnorm_));
    out.write((char*)&m_, sizeof(m_));
    out.write((char*)&n_, sizeof(n_));
    int32_t codesize = (int32_t)codes_.size();
    out.write((char*)&codesize, sizeof(codesize));
    out.write((char*)codes_.data(), (std::streamsize)codes_.size());
    pq_.save(out);
    if (qnorm_) {
      out.write((char*)normCodes_.data(), (std::streamsize)normCodes_.size());
      normPQ_.save(out);
    }
  }
  void load(std::istream& in) override {
    in.read((char*)&qnorm_, sizeof(qnorm_));
    in.read((char*)&m_, sizeof(m_));
    in.read((char*)&n_, sizeof(n_));
    int32_t codesize = 0;
    in.read((char*)&codesize, sizeof(codesize));
    codes_.assign(codesize > 0 ? codesize : 0, 0);
    if (codesize > 0) in.read((char*)codes_.data(), codesize);
    pq_.load(in);
    if (qnorm_) {
      normCodes_.assign(m_ > 0 ? (size_t)m_ : 0, 0);
      if (m_ > 0) in.read((char*)normCodes_.data(), (std::streamsize)m_);
      normPQ_.load(in);
    }
  }
  void dump(std::ostream&) const override {
    std::cerr << "Not supported for quantized models." << std::endl;
  }
};

