  }
  entry_type getType(int32_t id) const { return entries_[id].type; }
  bool isLabel(int32_t id) const { return entries_[id].type == entry_type::label; }
  const std::string& getWord(int32_t id) const { return entries_[id].word; }
  const std::string& getLabel(int32_t id) const {
    return entries_[nwords_ + id].word;
  }
  int32_t getId(const std::string& w) const {
    auto it = words_.find(w);
    if (it == words_.end()) return -1;
    return it->second;
  }
  int32_t getId(const std::string& w, uint32_t) const { return getId(w); }
  int64_t getCount(int32_t id) const { return entries_[id].count; }

  std::vector<int64_t> getCounts(entry_type type) const {
    std::vector<int64_t> counts;
    for (auto& e : entries_) {
      if (e.type == type) counts.push_back(e.count);
    }
    return counts;
  }

  void add(const std::string& w) {
    auto it = words_.find(w);
    if (it == words_.end()) {
      Entry e;
      e.word = w;
      e.count = 1;
      e.type = getWordType(w);
      entries_.push_back(std::move(e));
      words_[w] = (int32_t)entries_.size() - 1;
    } else {
      entries_[it->second].count++;
    }
  }

  bool readWord(std::istream& in, std::string& word) const {
    word.clear();
    char c;
    std::streambuf* sb = in.rdbuf();
    while (true) {
      int ci = sb->sbumpc();
      if (ci == std::streambuf::traits_type::eof()) {
        in.setstate(std::ios::eofbit);
        return !word.empty();
      }
      c = (char)ci;
      if (c == ' ' || c == '\n' || c == '\t' || c == '\v' || c == '\f' ||
          c == '\r' || c == '\0') {
        if (word.empty()) {
          if (c == '\n') {
            word = EOS;
            return true;
          }
          continue;
        } else {
          if (c == '\n') sb->sputbackc(c);
          return true;
        }
      }
      word.push_back(c);
    }
  }

  void readFromFile(const std::string& fname) {
    std::ifstream in(fname, std::ios::binary);
    if (!in.is_open()) {
      throw std::invalid_argument(fname + " cannot be opened for training!");
    }
    in.exceptions(std::ifstream::badbit);
    readFromInput(in);
  }
  void readFromInput(std::istream& in) {
    std::string line;
    int64_t minThreshold = 1;
    while (readWord(in, line)) {
      add(line);
      ntokens_++;
      if (ntokens_ % 1000000 == 0 && args_->verbose > 1) {
        std::cerr << "\rRead " << ntokens_ / 1000000 << "M words" << std::flush;
      }
      // Periodically prune the very largest vocabularies (rarely
      // reached in tests).  Kept for structural fidelity.
      if ((int64_t)entries_.size() > 30000000) {
        minThreshold++;
        threshold(minThreshold, minThreshold);
      }
    }
    threshold(args_->minCount, args_->minCountLabel);
    initTableDiscard();
    initNgrams();
  }

  void threshold(int64_t minCount, int64_t minCountLabel) {
    std::sort(entries_.begin(), entries_.end(), [](const Entry& a, const Entry& b) {
      if (a.type != b.type) return a.type < b.type;
      return a.count > b.count;
    });
    entries_.erase(
        std::remove_if(entries_.begin(), entries_.end(),
                       [&](const Entry& e) {
                         return (e.type == entry_type::word && e.count < minCount) ||
                                (e.type == entry_type::label && e.count < minCountLabel);
                       }),
        entries_.end());
    size_ = 0;
    nwords_ = 0;
    nlabels_ = 0;
    words_.clear();
    for (auto& e : entries_) {
      if (e.type == entry_type::word) nwords_++;
      else nlabels_++;
      words_[e.word] = size_++;
    }
