  void initTableDiscard() {
    pdiscard_.clear();
    pdiscard_.reserve(entries_.size());
    for (auto& e : entries_) {
      real f = (real)e.count / (real)ntokens_;
      pdiscard_.push_back(std::sqrt((real)args_->t / f) + (real)args_->t / f);
    }
  }
  bool discard(int32_t id, real rand) const {
    if (id < 0 || id >= (int32_t)pdiscard_.size()) return false;
    return rand > pdiscard_[id];
