  void computeSubwords(const std::string& word, std::vector<int32_t>& ids,
                       std::vector<std::string>* ngrams = nullptr) const {
    size_t len = word.size();
    for (size_t i = 0; i < len; i++) {
      if ((static_cast<unsigned char>(word[i]) & 0xC0) == 0x80) continue;
      std::string ngram;
      int32_t ngramSize = 0;
      for (size_t j = i; j < len && ngramSize < args_->maxn; j++) {
        ngram.push_back(word[j]);
        if ((static_cast<unsigned char>(word[j]) & 0xC0) != 0x80) ngramSize++;
        if (ngramSize >= args_->minn &&
            !(ngramSize == 1 && (i == 0 || j == len - 1))) {
          if (ngrams != nullptr) {
            ngrams->push_back(ngram);
            ids.push_back(getSubwordId(ngram));
          } else {
            int32_t id = getSubwordId(ngram);
            if (id >= 0) ids.push_back(id);
