  }

  void addWordNgrams(std::vector<int32_t>& line,
                     const std::vector<int32_t>& hashes, int32_t n) const {
    if (args_->bucket <= 0) return;
    for (size_t i = 0; i < hashes.size(); i++) {
      uint64_t h = (uint64_t)(int64_t)hashes[i];
      for (size_t j = i + 1; j < hashes.size() && (int32_t)(j - i) < n; j++) {
        h = h * 116049371ULL + (uint64_t)(int64_t)hashes[j];
        int32_t bucketId = (int32_t)(h % (uint64_t)args_->bucket);
        int32_t id = getSubwordIdFromHash(bucketId);
        if (id >= 0) line.push_back(id);
      }
    }
  }

  // Training / supervised-style line reader: expands subwords,
  // gathers labels, appends word n-grams.  Returns tokens read.
  int32_t getLine(std::istream& in, std::vector<int32_t>& line,
                  std::vector<int32_t>& labels) const {
    std::vector<int32_t> wordHashes;
    std::string token;
    line.clear();
    labels.clear();
    int32_t ntokens = 0;
    while (readWord(in, token)) {
      uint32_t h = hashString(token);
      int32_t wid = getId(token);
      entry_type type = wid < 0 ? getWordType(token) : getType(wid);
      ntokens++;
      if (type == entry_type::word) {
        addSubwords(line, token, wid);
        wordHashes.push_back((int32_t)h);
      } else if (type == entry_type::label && wid >= 0) {
        labels.push_back(wid - nwords_);
      }
      if (token == EOS) break;
      if ((int32_t)line.size() >= MAX_LINE_SIZE) break;
    }
    addWordNgrams(line, wordHashes, args_->wordNgrams);
    return ntokens;
  }

  // Unsupervised training line reader: returns word ids that survive
  // frequency subsampling.  Returns tokens read from the stream.
  int32_t getLine(std::istream& in, std::vector<int32_t>& line,
                  std::minstd_rand& rng) const {
    std::string token;
    line.clear();
    int32_t ntokens = 0;
    std::uniform_real_distribution<> uniform(0, 1);
    while (readWord(in, token)) {
      int32_t wid = getId(token);
      ntokens++;
      if (wid >= 0 && getType(wid) == entry_type::word) {
        if (!discard(wid, (real)uniform(rng))) {
          line.push_back(wid);
        }
      }
      if (token == EOS) break;
      if ((int32_t)line.size() >= MAX_LINE_SIZE) break;
    }
