};

class Dictionary {
 public:
  std::shared_ptr<Args> args_;
  std::vector<Entry> entries_;
  std::unordered_map<std::string, int32_t> words_;
  std::vector<real> pdiscard_;
  int32_t size_ = 0;
  int32_t nwords_ = 0;
  int32_t nlabels_ = 0;
  int64_t ntokens_ = 0;
  int64_t pruneidxSize_ = -1;
  std::unordered_map<int32_t, int32_t> pruneidx_;

  explicit Dictionary(std::shared_ptr<Args> args) : args_(std::move(args)) {
    // Period/reference implementation reserves a very large table;
    // a modest reserve gives equivalent observable behaviour.
    words_.reserve(1024);
  }

  int32_t size() const { return size_; }
  int32_t nwords() const { return nwords_; }
  int32_t nlabels() const { return nlabels_; }
  int64_t ntokens() const { return ntokens_; }

  entry_type getWordType(const std::string& w) const {
    if (w.rfind(args_->label, 0) == 0) return entry_type::label;
    return entry_type::word;
  }
  entry_type getType(int32_t id) const { return entries_[id].type; }
  bool isLabel(int32_t id) const { return entries_[id].type == entry_type::label; }
  const std::string& getWord(int32_t id) const { return entries_[id].word; }
  const std::string& getLabel(int32_t id) const {
    return entries_[nwords_ + id].word;
  }
  int32_t getId(const std::string& w) const {
    auto it = words_.find(w);
    if (it == words_.end()) return -1;
    return it->second;
  }
  int32_t getId(const std::string& w, uint32_t) const { return getId(w); }
  int64_t getCount(int32_t id) const { return entries_[id].count; }

  std::vector<int64_t> getCounts(entry_type type) const {
    std::vector<int64_t> counts;
    for (auto& e : entries_) {
      if (e.type == type) counts.push_back(e.count);
    }
    return counts;
  }

  void add(const std::string& w) {
    auto it = words_.find(w);
    if (it == words_.end()) {
      Entry e;
      e.word = w;
      e.count = 1;
      e.type = getWordType(w);
      entries_.push_back(std::move(e));
      words_[w] = (int32_t)entries_.size() - 1;
    } else {
      entries_[it->second].count++;
    }
  }

  bool readWord(std::istream& in, std::string& word) const {
    word.clear();
    char c;
    std::streambuf* sb = in.rdbuf();
    while (true) {
      int ci = sb->sbumpc();
      if (ci == std::streambuf::traits_type::eof()) {
        in.setstate(std::ios::eofbit);
        return !word.empty();
      }
      c = (char)ci;
      if (c == ' ' || c == '\n' || c == '\t' || c == '\v' || c == '\f' ||
          c == '\r' || c == '\0') {
        if (word.empty()) {
          if (c == '\n') {
            word = EOS;
            return true;
          }
          continue;
        } else {
          if (c == '\n') sb->sputbackc(c);
          return true;
        }
      }
      word.push_back(c);
    }
  }

  void readFromFile(const std::string& fname) {
    std::ifstream in(fname, std::ios::binary);
    if (!in.is_open()) {
      throw std::invalid_argument(fname + " cannot be opened for training!");
