    readFromInput(in);
  }
  void readFromInput(std::istream& in) {
    std::string line;
    int64_t minThreshold = 1;
    while (readWord(in, line)) {
      add(line);
      ntokens_++;
      if (ntokens_ % 1000000 == 0 && args_->verbose > 1) {
        std::cerr << "\rRead " << ntokens_ / 1000000 << "M words" << std::flush;
      }
      // Periodically prune the very largest vocabularies (rarely
      // reached in tests).  Kept for structural fidelity.
      if ((int64_t)entries_.size() > 30000000) {
        minThreshold++;
        threshold(minThreshold, minThreshold);
      }
    }
    threshold(args_->minCount, args_->minCountLabel);
    initTableDiscard();
    initNgrams();
  }

  void threshold(int64_t minCount, int64_t minCountLabel) {
    std::sort(entries_.begin(), entries_.end(), [](const Entry& a, const Entry& b) {
      if (a.type != b.type) return a.type < b.type;
      return a.count > b.count;
    });
    entries_.erase(
        std::remove_if(entries_.begin(), entries_.end(),
                       [&](const Entry& e) {
                         return (e.type == entry_type::word && e.count < minCount) ||
                                (e.type == entry_type::label && e.count < minCountLabel);
                       }),
        entries_.end());
    size_ = 0;
    nwords_ = 0;
    nlabels_ = 0;
    words_.clear();
    for (auto& e : entries_) {
      if (e.type == entry_type::word) nwords_++;
      else nlabels_++;
      words_[e.word] = size_++;
    }
  }

  void initTableDiscard() {
    pdiscard_.clear();
    pdiscard_.reserve(entries_.size());
    for (auto& e : entries_) {
      real f = (real)e.count / (real)ntokens_;
      pdiscard_.push_back(std::sqrt((real)args_->t / f) + (real)args_->t / f);
    }
  }
  bool discard(int32_t id, real rand) const {
    if (id < 0 || id >= (int32_t)pdiscard_.size()) return false;
    return rand > pdiscard_[id];
  }

  int32_t getSubwordId(const std::string& ngram) const {
    if (args_->bucket <= 0) return -1;
    uint32_t h = hashString(ngram) % (uint32_t)args_->bucket;
    return getSubwordIdFromHash((int32_t)h);
  }
  int32_t getSubwordIdFromHash(int32_t h) const {
    if (pruneidx_.empty()) {
