      return nwords_ + h;
    }
    auto it = pruneidx_.find(h);
    if (it == pruneidx_.end()) return -1;
    return nwords_ + it->second;
  }

  void computeSubwords(const std::string& word, std::vector<int32_t>& ids,
                       std::vector<std::string>* ngrams = nullptr) const {
    size_t len = word.size();
    for (size_t i = 0; i < len; i++) {
      if ((static_cast<unsigned char>(word[i]) & 0xC0) == 0x80) continue;
      std::string ngram;
      int32_t ngramSize = 0;
      for (size_t j = i; j < len && ngramSize < args_->maxn; j++) {
        ngram.push_back(word[j]);
        if ((static_cast<unsigned char>(word[j]) & 0xC0) != 0x80) ngramSize++;
        if (ngramSize >= args_->minn &&
            !(ngramSize == 1 && (i == 0 || j == len - 1))) {
          if (ngrams != nullptr) {
            ngrams->push_back(ngram);
            ids.push_back(getSubwordId(ngram));
          } else {
            int32_t id = getSubwordId(ngram);
            if (id >= 0) ids.push_back(id);
          }
        }
      }
    }
  }

  void initNgrams() {
    for (int32_t i = 0; i < (int32_t)entries_.size(); i++) {
      auto& e = entries_[i];
      e.subwords.clear();
      e.subwords.push_back(i);
      if (e.word != EOS && args_->maxn > 0) {
        computeSubwords(BOW + e.word + EOW, e.subwords);
      }
    }
  }

  const std::vector<int32_t>& getSubwords(int32_t id) const {
    return entries_[id].subwords;
  }
  void getSubwords(const std::string& word, std::vector<int32_t>& ids) const {
    ids.clear();
    if (word == EOS) {
      int32_t id = getId(word);
      if (id >= 0) ids.push_back(id);
      return;
    }
    int32_t wid = getId(word);
    if (wid >= 0) {
      ids = entries_[wid].subwords;
      return;
    }
    if (word.empty()) return;
    if (args_->maxn > 0) computeSubwords(BOW + word + EOW, ids);
  }
  void getSubwords(const std::string& word, std::vector<std::string>& ngrams,
                   std::vector<int32_t>& ids) const {
    ngrams.clear();
    ids.clear();
    if (word.empty()) return;
    int32_t wid = getId(word);
    if (wid >= 0) {
      ngrams.push_back(word);
      ids.push_back(wid);
      if (word == EOS) return;
    }
    if (args_->maxn > 0) computeSubwords(BOW + word + EOW, ids, &ngrams);
  }

  void addSubwords(std::vector<int32_t>& line, const std::string& token,
                   int32_t wid) const {
    if (wid < 0) {
      if (token != EOS && args_->maxn > 0) {
        computeSubwords(BOW + token + EOW, line);
      }
    } else {
      if (args_->maxn <= 0) {
        line.push_back(wid);
      } else {
        auto& sw = entries_[wid].subwords;
        line.insert(line.end(), sw.begin(), sw.end());
      }
    }
  }

  void addWordNgrams(std::vector<int32_t>& line,
                     const std::vector<int32_t>& hashes, int32_t n) const {
    if (args_->bucket <= 0) return;
    for (size_t i = 0; i < hashes.size(); i++) {
      uint64_t h = (uint64_t)(int64_t)hashes[i];
      for (size_t j = i + 1; j < hashes.size() && (int32_t)(j - i) < n; j++) {
        h = h * 116049371ULL + (uint64_t)(int64_t)hashes[j];
        int32_t bucketId = (int32_t)(h % (uint64_t)args_->bucket);
        int32_t id = getSubwordIdFromHash(bucketId);
        if (id >= 0) line.push_back(id);
      }
    }
  }

  // Training / supervised-style line reader: expands subwords,
  // gathers labels, appends word n-grams.  Returns tokens read.
  int32_t getLine(std::istream& in, std::vector<int32_t>& line,
                  std::vector<int32_t>& labels) const {
    std::vector<int32_t> wordHashes;
    std::string token;
    line.clear();
    labels.clear();
    int32_t ntokens = 0;
    while (readWord(in, token)) {
      uint32_t h = hashString(token);
      int32_t wid = getId(token);
      entry_type type = wid < 0 ? getWordType(token) : getType(wid);
      ntokens++;
      if (type == entry_type::word) {
        addSubwords(line, token, wid);
        wordHashes.push_back((int32_t)h);
      } else if (type == entry_type::label && wid >= 0) {
        labels.push_back(wid - nwords_);
      }
      if (token == EOS) break;
      if ((int32_t)line.size() >= MAX_LINE_SIZE) break;
    }
    addWordNgrams(line, wordHashes, args_->wordNgrams);
    return ntokens;
  }

  // Unsupervised training line reader: returns word ids that survive
  // frequency subsampling.  Returns tokens read from the stream.
  int32_t getLine(std::istream& in, std::vector<int32_t>& line,
                  std::minstd_rand& rng) const {
    std::string token;
    line.clear();
    int32_t ntokens = 0;
    std::uniform_real_distribution<> uniform(0, 1);
    while (readWord(in, token)) {
      int32_t wid = getId(token);
      ntokens++;
      if (wid >= 0 && getType(wid) == entry_type::word) {
        if (!discard(wid, (real)uniform(rng))) {
          line.push_back(wid);
        }
      }
      if (token == EOS) break;
      if ((int32_t)line.size() >= MAX_LINE_SIZE) break;
    }
    return ntokens;
  }

  void save(std::ostream& out) const {
    out.write((char*)&size_, sizeof(size_));
    out.write((char*)&nwords_, sizeof(nwords_));
    out.write((char*)&nlabels_, sizeof(nlabels_));
    out.write((char*)&ntokens_, sizeof(ntokens_));
    int64_t psz = pruneidx_.empty() ? -1 : (int64_t)pruneidx_.size();
    out.write((char*)&psz, sizeof(psz));
    for (auto& e : entries_) {
      out.write(e.word.c_str(), (std::streamsize)e.word.size() + 1);
      out.write((char*)&e.count, sizeof(e.count));
      int8_t t = (int8_t)e.type;
      out.write((char*)&t, sizeof(t));
    }
    for (auto& kv : pruneidx_) {
      out.write((char*)&kv.first, sizeof(kv.first));
      out.write((char*)&kv.second, sizeof(kv.second));
    }
  }
  void load(std::istream& in) {
    in.read((char*)&size_, sizeof(size_));
    in.read((char*)&nwords_, sizeof(nwords_));
    in.read((char*)&nlabels_, sizeof(nlabels_));
    in.read((char*)&ntokens_, sizeof(ntokens_));
    in.read((char*)&pruneidxSize_, sizeof(pruneidxSize_));
    entries_.clear();
    words_.clear();
    for (int32_t i = 0; i < size_; i++) {
      Entry e;
      char c;
      while (in.get(c) && c != '\0') e.word.push_back(c);
      in.read((char*)&e.count, sizeof(e.count));
      int8_t t = 0;
      in.read((char*)&t, sizeof(t));
      e.type = (entry_type)t;
      entries_.push_back(std::move(e));
      words_[entries_.back().word] = i;
    }
    pruneidx_.clear();
    for (int64_t i = 0; i < pruneidxSize_; i++) {
      int32_t a = 0, b = 0;
      in.read((char*)&a, sizeof(a));
      in.read((char*)&b, sizeof(b));
      pruneidx_[a] = b;
    }
    initTableDiscard();
    initNgrams();
  }
  void dump(std::ostream& out) const {
    out << size_ << std::endl;
    for (auto& e : entries_) {
      out << e.word << " " << e.count << " "
          << (e.type == entry_type::label ? "label" : "word") << std::endl;
    }
  }

  // Build pruning mapping for quantization with cutoff. Selected
  // ids are embedding row ids to retain (word rows plus bucket rows
  // in ranked order).
  void prune(const std::vector<int32_t>& selected) {
    // selected contains word ids [0..nwords) then retained rows.
    pruneidx_.clear();
    int32_t newBucket = 0;
    // Map original bucket (row-nwords) -> compact bucket for rows
    // beyond the word rows, in the order they appear in selected.
    std::vector<int32_t> retainedRows;
    for (int32_t id : selected) {
      if (id >= nwords_) retainedRows.push_back(id);
    }
    for (int32_t id : retainedRows) {
      pruneidx_[id - nwords_] = newBucket++;
    }
    pruneidxSize_ = pruneidx_.empty() ? -1 : (int64_t)pruneidx_.size();
    initNgrams();
  }
};

