// ------------------------------ Loss / model state ------------------------------

struct PredictionsHeap {
  // Helpers shared by losses below
};

class Loss {
 public:
  std::shared_ptr<Matrix> wo_;
  int32_t osize_;
  std::vector<real> t_sigmoid_;
  std::vector<real> t_log_;

  Loss(std::shared_ptr<Matrix> wo, int32_t osize)
      : wo_(std::move(wo)), osize_(osize) {
    t_sigmoid_.reserve(SIGMOID_TABLE_SIZE + 1);
    for (int32_t i = 0; i <= SIGMOID_TABLE_SIZE; i++) {
      real x = (real)i * 2 * MAX_SIGMOID / SIGMOID_TABLE_SIZE - MAX_SIGMOID;
      t_sigmoid_.push_back(1.0f / (1.0f + std::exp(-x)));
    }
    t_log_.reserve(LOG_TABLE_SIZE + 1);
    for (int32_t i = 0; i <= LOG_TABLE_SIZE; i++) {
      real x = ((real)i + 1e-5f) / LOG_TABLE_SIZE;
      t_log_.push_back(std::log(x));
    }
  }
  virtual ~Loss() {}

  real sigmoid(real x) const {
    if (x < -MAX_SIGMOID) return 0.0f;
    if (x > MAX_SIGMOID) return 1.0f;
    int32_t i = (int32_t)((x + MAX_SIGMOID) * SIGMOID_TABLE_SIZE / (2 * MAX_SIGMOID));
    return t_sigmoid_[i];
  }
  real log(real x) const {
    if (x > 1.0f) return 0.0f;
    int32_t i = (int32_t)(x * LOG_TABLE_SIZE);
    return t_log_[i];
  }

  struct State {
    Vector hidden;
    Vector output;
    Vector grad;
    real loss = 0;
    int64_t nexamples = 0;
    std::minstd_rand rng;
    State() : hidden(0), output(0), grad(0) {}
    State(int32_t dim, int32_t osize, unsigned int seed)
        : hidden(dim), output(osize), grad(dim), rng(seed) {}
  };

  static bool addPrediction(std::vector<std::pair<real, int32_t>>& heap,
                            real prob, int32_t label, int32_t k, real threshold) {
    if (prob < threshold) return false;
    real logProb = std::log(prob + 1e-5f);
    if ((int32_t)heap.size() < k) {
      heap.emplace_back(logProb, label);
      std::push_heap(heap.begin(), heap.end(), comparePairsDesc);
      return true;
    }
    if (k <= 0) return false;
    if (logProb > heap.front().first) {
      std::pop_heap(heap.begin(), heap.end(), comparePairsDesc);
      heap.back() = {logProb, label};
      std::push_heap(heap.begin(), heap.end(), comparePairsDesc);
      return true;
    }
    return false;
  }
  static bool comparePairsDesc(const std::pair<real, int32_t>& a,
                               const std::pair<real, int32_t>& b) {
    return a.first > b.first;
  }

  virtual real forward(const std::vector<int32_t>& input, int32_t target,
                       State& state, real lr, bool backprop) = 0;
  virtual void predict(const std::vector<int32_t>& input, int32_t k, real threshold,
                       std::vector<std::pair<real, int32_t>>& predictions,
                       State& state) const = 0;
  // Hidden vector is computed by the caller into state.hidden.
  void backward(const std::vector<int32_t>& input, State& state,
                const std::shared_ptr<Matrix>& wi) {
    if (input.empty()) return;
    real scale = 1.0f / (real)input.size();
    for (int32_t id : input) {
      wi->addVectorToRow(state.grad, id, scale);
    }
  }
};

class BinaryLogisticLoss : public Loss {
 public:
  using Loss::Loss;
  real binaryLogistic(int32_t target, State& state, bool label, real lr,
                      bool backprop) {
    real score = sigmoid(wo_->dotRow(state.hidden, target));
    if (backprop) {
      real alpha = lr * ((real)label - score);
      state.grad.addRow(
          *std::dynamic_pointer_cast<DenseMatrix>(wo_), target, alpha);
      // DenseMatrix assumed during training; quantized output is not
      // updated (quantized models are inference-only).
      wo_->addVectorToRow(state.hidden, target, alpha);
    }
    return label ? -log(score) : -log(1.0f - score);
  }
  // A version of binaryLogistic that does not assume dense output
  // for the grad accumulation.
  real binaryLogisticGeneric(int32_t target, State& state, bool label, real lr,
                             bool backprop) {
    real score = sigmoid(wo_->dotRow(state.hidden, target));
    if (backprop) {
      real alpha = lr * ((real)label - score);
      // grad += alpha * wo row  (row snapshot via a temp vector)
      Vector row(state.hidden.size());
      row.zero();
      wo_->addRowToVector(row, target);
      for (int64_t j = 0; j < row.size(); j++) state.grad[j] += alpha * row[j];
      wo_->addVectorToRow(state.hidden, target, alpha);
    }
    return label ? -log(score) : -log(1.0f - score);
  }
};

class NegativeSamplingLoss : public BinaryLogisticLoss {
 public:
  int32_t neg_;
  std::vector<int32_t> negatives_;
  size_t negPos_ = 0;
  std::uniform_int_distribution<int32_t> uniform_;
  NegativeSamplingLoss(std::shared_ptr<Matrix> wo, int32_t osize,
                       const std::vector<int64_t>& counts, int32_t neg)
      : BinaryLogisticLoss(std::move(wo), osize), neg_(neg) {
    initNegatives(counts);
    uniform_ = std::uniform_int_distribution<int32_t>(
        0, negatives_.empty() ? 0 : (int32_t)negatives_.size() - 1);
  }
  void initNegatives(const std::vector<int64_t>& counts) {
    real z = 0;
    for (int64_t c : counts) z += std::pow((real)c, 0.5f);
    if (z == 0) return;
    for (size_t i = 0; i < counts.size(); i++) {
      real c = std::pow((real)counts[i], 0.5f);
      int64_t cnt = (int64_t)(c * (real)NEGATIVE_TABLE_SIZE / z);
      for (int64_t j = 0; j < cnt; j++) negatives_.push_back((int32_t)i);
    }
  }
  int32_t getNegative(int32_t target, std::minstd_rand& rng) {
    int32_t n;
    do {
      n = negatives_[uniform_(rng)];
    } while (n == target);
    return n;
  }
  real forward(const std::vector<int32_t>&, int32_t target, State& state,
               real lr, bool backprop) override {
    real loss = 0;
    loss += binaryLogisticGeneric(target, state, true, lr, backprop);
    for (int32_t i = 0; i < neg_; i++) {
      int32_t n = getNegative(target, state.rng);
      loss += binaryLogisticGeneric(n, state, false, lr, backprop);
    }
    return loss;
  }
  void predict(const std::vector<int32_t>&, int32_t k, real threshold,
               std::vector<std::pair<real, int32_t>>& predictions,
               State& state) const override {
    for (int32_t i = 0; i < osize_; i++) {
      real p = sigmoid(wo_->dotRow(state.hidden, i));
      addPrediction(predictions, p, i, k, threshold);
    }
  }
};

class OneVsAllLoss : public BinaryLogisticLoss {
 public:
  using BinaryLogisticLoss::BinaryLogisticLoss;
  real forward(const std::vector<int32_t>&, int32_t target, State& state,
               real lr, bool backprop) override {
    real loss = 0;
    for (int32_t i = 0; i < osize_; i++) {
      loss += binaryLogisticGeneric(i, state, i == target, lr, backprop);
    }
    return loss;
  }
  void predict(const std::vector<int32_t>&, int32_t k, real threshold,
               std::vector<std::pair<real, int32_t>>& predictions,
               State& state) const override {
    for (int32_t i = 0; i < osize_; i++) {
      real p = sigmoid(wo_->dotRow(state.hidden, i));
      addPrediction(predictions, p, i, k, threshold);
    }
  }
};

class HierarchicalSoftmaxLoss : public BinaryLogisticLoss {
 public:
  struct Node {
    int32_t left = -1;
    int32_t right = -1;
    int32_t parent = -1;
    int32_t count = 0;
    bool code = false;
  };
  std::vector<Node> tree_;
  std::vector<std::vector<int32_t>> paths_;
  std::vector<std::vector<bool>> codes_;

  HierarchicalSoftmaxLoss(std::shared_ptr<Matrix> wo, int32_t osize,
                          const std::vector<int64_t>& counts)
      : BinaryLogisticLoss(std::move(wo), osize) {
    buildTree(counts);
  }
  void buildTree(const std::vector<int64_t>& counts) {
    int32_t osize = (int32_t)counts.size();
    if (osize == 0) return;
    tree_.assign(2 * osize - 1, Node());
    for (int32_t i = 0; i < osize; i++) {
      tree_[i].count = (int32_t)counts[i];
    }
    for (int32_t i = osize; i < 2 * osize - 1; i++) {
      tree_[i].count = 1000000000;
    }
    int32_t leaf = osize - 1;
    int32_t node = osize;
    for (int32_t i = osize; i < 2 * osize - 1; i++) {
      int32_t minIdx[2] = {-1, -1};
      for (int32_t k = 0; k < 2; k++) {
        if (leaf >= 0 && tree_[leaf].count < tree_[node].count) {
          minIdx[k] = leaf--;
        } else {
          minIdx[k] = node++;
        }
      }
      tree_[i].left = minIdx[0];
      tree_[i].right = minIdx[1];
      tree_[i].count = tree_[minIdx[0]].count + tree_[minIdx[1]].count;
      tree_[minIdx[0]].parent = i;
      tree_[minIdx[1]].parent = i;
      tree_[minIdx[1]].code = true;
    }
    paths_.assign(osize, {});
    codes_.assign(osize, {});
    for (int32_t i = 0; i < osize; i++) {
      int32_t cur = i;
      std::vector<int32_t> path;
      std::vector<bool> code;
      while (tree_[cur].parent >= 0) {
        path.push_back(tree_[cur].parent - osize);
        code.push_back(tree_[cur].code);
        cur = tree_[cur].parent;
      }
      std::reverse(path.begin(), path.end());
      std::reverse(code.begin(), code.end());
      paths_[i] = path;
      codes_[i] = code;
    }
  }
  real forward(const std::vector<int32_t>&, int32_t target, State& state,
               real lr, bool backprop) override {
    real loss = 0;
    if (target < 0 || target >= (int32_t)paths_.size()) return loss;
    auto& path = paths_[target];
    auto& code = codes_[target];
    for (size_t i = 0; i < path.size(); i++) {
      loss += binaryLogisticGeneric(path[i], state, code[i], lr, backprop);
    }
    return loss;
  }
  void predict(const std::vector<int32_t>&, int32_t k, real threshold,
               std::vector<std::pair<real, int32_t>>& predictions,
               State& state) const override {
    // Compute each leaf probability as the product of branch
    // probabilities along its Huffman path.
    for (int32_t leaf = 0; leaf < (int32_t)paths_.size(); leaf++) {
      real prob = 1.0f;
      auto& path = paths_[leaf];
      auto& code = codes_[leaf];
      for (size_t i = 0; i < path.size(); i++) {
        real s = sigmoid(wo_->dotRow(state.hidden, path[i]));
        prob *= code[i] ? s : (1.0f - s);
      }
      addPrediction(predictions, prob, leaf, k, threshold);
    }
  }
};

class SoftmaxLoss : public Loss {
 public:
  using Loss::Loss;
  void computeOutput(State& state) const {
    wo_->multiplyRow(state.hidden, state.output);
    real maxv = state.output[0];
    for (int64_t i = 1; i < state.output.size(); i++) maxv = std::max(maxv, state.output[i]);
    real sum = 0;
    for (int64_t i = 0; i < state.output.size(); i++) {
      state.output[i] = std::exp(state.output[i] - maxv);
      sum += state.output[i];
    }
    for (int64_t i = 0; i < state.output.size(); i++) state.output[i] /= sum;
  }
  real forward(const std::vector<int32_t>&, int32_t target, State& state,
               real lr, bool backprop) override {
    computeOutput(state);
    if (backprop) {
      for (int32_t i = 0; i < osize_; i++) {
        real label = (i == target) ? 1.0f : 0.0f;
        real alpha = lr * (state.output[i] - label);
        Vector row(state.hidden.size());
        row.zero();
        wo_->addRowToVector(row, i);
        for (int64_t j = 0; j < row.size(); j++) state.grad[j] += alpha * row[j];
        wo_->addVectorToRow(state.hidden, i, -alpha);
      }
    }
    return -log(state.output[target]);
  }
  void predict(const std::vector<int32_t>&, int32_t k, real threshold,
               std::vector<std::pair<real, int32_t>>& predictions,
               State& state) const override {
    computeOutput(state);
    for (int32_t i = 0; i < osize_; i++) {
      addPrediction(predictions, state.output[i], i, k, threshold);
    }
  }
};

