                          const std::vector<int64_t>& counts)
      : BinaryLogisticLoss(std::move(wo), osize) {
    buildTree(counts);
  }
  void buildTree(const std::vector<int64_t>& counts) {
    int32_t osize = (int32_t)counts.size();
    if (osize == 0) return;
    tree_.assign(2 * osize - 1, Node());
    for (int32_t i = 0; i < osize; i++) {
      tree_[i].count = (int32_t)counts[i];
    }
    for (int32_t i = osize; i < 2 * osize - 1; i++) {
      tree_[i].count = 1000000000;
    }
    int32_t leaf = osize - 1;
    int32_t node = osize;
    for (int32_t i = osize; i < 2 * osize - 1; i++) {
      int32_t minIdx[2] = {-1, -1};
      for (int32_t k = 0; k < 2; k++) {
        if (leaf >= 0 && tree_[leaf].count < tree_[node].count) {
          minIdx[k] = leaf--;
        } else {
          minIdx[k] = node++;
        }
      }
      tree_[i].left = minIdx[0];
      tree_[i].right = minIdx[1];
      tree_[i].count = tree_[minIdx[0]].count + tree_[minIdx[1]].count;
      tree_[minIdx[0]].parent = i;
      tree_[minIdx[1]].parent = i;
      tree_[minIdx[1]].code = true;
    }
    paths_.assign(osize, {});
    codes_.assign(osize, {});
    for (int32_t i = 0; i < osize; i++) {
      int32_t cur = i;
      std::vector<int32_t> path;
      std::vector<bool> code;
      while (tree_[cur].parent >= 0) {
        path.push_back(tree_[cur].parent - osize);
        code.push_back(tree_[cur].code);
        cur = tree_[cur].parent;
      }
      std::reverse(path.begin(), path.end());
      std::reverse(code.begin(), code.end());
      paths_[i] = path;
      codes_[i] = code;
    }
