    // probabilities along its Huffman path.
    for (int32_t leaf = 0; leaf < (int32_t)paths_.size(); leaf++) {
      real prob = 1.0f;
      auto& path = paths_[leaf];
      auto& code = codes_[leaf];
      for (size_t i = 0; i < path.size(); i++) {
