class SoftmaxLoss : public Loss {
 public:
  using Loss::Loss;
  void computeOutput(State& state) const {
    wo_->multiplyRow(state.hidden, state.output);
    real maxv = state.output[0];
    for (int64_t i = 1; i < state.output.size(); i++) maxv = std::max(maxv, state.output[i]);
    real sum = 0;
    for (int64_t i = 0; i < state.output.size(); i++) {
      state.output[i] = std::exp(state.output[i] - maxv);
      sum += state.output[i];
    }
    for (int64_t i = 0; i < state.output.size(); i++) state.output[i] /= sum;
  }
  real forward(const std::vector<int32_t>&, int32_t target, State& state,
               real lr, bool backprop) override {
