               std::vector<std::pair<real, int32_t>>& predictions,
               State& state) const override {
    computeOutput(state);
    for (int32_t i = 0; i < osize_; i++) {
      addPrediction(predictions, state.output[i], i, k, threshold);
    }
  }
};

