    for (auto& kv : rows) {
      pretrainedRows_[kv.first] = kv.second;
      int32_t existing = dict_->getId(kv.first);
      if (existing >= 0) {
        // increment count of the existing entry (find in words/labels)
        bool done = false;
        for (auto& e : words) if (e.word == kv.first) { e.count++; done = true; break; }
        if (!done) for (auto& e : labels) if (e.word == kv.first) { e.count++; break; }
