      } else {
        Entry e;
        e.word = kv.first;
        e.count = 1;
        e.type = entry_type::word;
        words.push_back(std::move(e));
        dict_->ntokens_++;
      }
    }
    dict_->entries_.clear();
    dict_->entries_.insert(dict_->entries_.end(), words.begin(), words.end());
    dict_->entries_.insert(dict_->entries_.end(), labels.begin(), labels.end());
    dict_->nwords_ = (int32_t)words.size();
    dict_->nlabels_ = (int32_t)labels.size();
    dict_->size_ = dict_->nwords_ + dict_->nlabels_;
    dict_->words_.clear();
    for (int32_t i = 0; i < dict_->size_; i++) dict_->words_[dict_->entries_[i].word] = i;
    dict_->initTableDiscard();
    dict_->initNgrams();
  }

