// ------------------------------ FastText core ------------------------------

class FastText {
 public:
  std::shared_ptr<Args> args_;
  std::shared_ptr<Dictionary> dict_;
  std::shared_ptr<Matrix> input_;
  std::shared_ptr<Matrix> output_;
  std::shared_ptr<Loss> loss_;
  bool quant_ = false;
  bool quantOut_ = false;
  std::atomic<int64_t> tokenCount_{0};
  std::atomic<real> lossAgg_{0};
  std::atomic<int64_t> nexAgg_{0};
  std::shared_ptr<DenseMatrix> wordVectors_;
  std::chrono::steady_clock::time_point trainStart_;
  // Pretrained rows applied after slice initialization
  std::unordered_map<std::string, std::vector<real>> pretrainedRows_;

  FastText() : args_(std::make_shared<Args>()) {}

  std::shared_ptr<Dictionary> getDictionary() const { return dict_; }
  std::shared_ptr<Matrix> getInput() const { return input_; }
  std::shared_ptr<Matrix> getOutput() const { return output_; }
  std::shared_ptr<Args> getArgs() const { return args_; }

  void createLoss() {
    int32_t osize = args_->model == model_name::sup ? dict_->nlabels() : dict_->nwords();
    auto counts = dict_->getCounts(
        args_->model == model_name::sup ? entry_type::label : entry_type::word);
    switch (args_->loss) {
      case loss_name::hs:
        loss_ = std::make_shared<HierarchicalSoftmaxLoss>(output_, osize, counts);
        break;
      case loss_name::ns:
        loss_ = std::make_shared<NegativeSamplingLoss>(output_, osize, counts, args_->neg);
        break;
      case loss_name::softmax:
        loss_ = std::make_shared<SoftmaxLoss>(output_, osize);
        break;
      case loss_name::onevsall:
        loss_ = std::make_shared<OneVsAllLoss>(output_, osize);
        break;
      default:
        throw std::runtime_error("Unknown loss");
    }
    // Trigger early validation of loss name like the reference (lossName
    // throws for unknown values encountered while loading a model).
    (void)lossName(args_->loss);
  }

  void getWordVector(Vector& vec, const std::string& word) const {
    vec.zero();
    std::vector<int32_t> ids;
    dict_->getSubwords(word, ids);
    if (ids.empty()) return;
    for (int32_t id : ids) {
      if (id >= 0 && id < input_->size(0)) input_->addRowToVector(vec, id);
    }
    vec.mul(1.0f / (real)ids.size());
  }

  void getSentenceVector(std::istream& in, Vector& vec) {
    std::vector<int32_t> line;
    std::vector<int32_t> labels;
    dict_->getLine(in, line, labels);
    getSentenceVector(line, vec);
  }
  void getSentenceVector(const std::vector<int32_t>& line, Vector& vec) const {
    if (args_->model == model_name::sup) {
      vec.zero();
      if (line.empty()) return;
      for (int32_t id : line) {
        if (id >= 0 && id < input_->size(0)) input_->addRowToVector(vec, id);
      }
      vec.mul(1.0f / (real)line.size());
    } else {
      // Unsupervised: average of word vectors of tokens present in
      // the (subword-expanded) line is not used here; the reference
      // reads raw tokens in its istream overload.  This overload is
      // reached with word ids from the istream wrapper below.
      vec.zero();
      if (line.empty()) return;
      for (int32_t id : line) {
        if (id >= 0 && id < input_->size(0)) input_->addRowToVector(vec, id);
      }
      vec.mul(1.0f / (real)line.size());
    }
  }
  // Sentence vector exactly as printed: for non-supervised models
  // this averages word vectors (each itself a subword average) for
  // every whitespace token and L2-normalizes.  For supervised it is
  // the mean input (hidden) vector.
  void sentenceVectorFromStream(std::istream& in, Vector& vec) {
    if (args_->model == model_name::sup) {
      getSentenceVector(in, vec);
      return;
    }
    std::vector<int32_t> line;
    std::vector<int32_t> labels;
    // Re-read tokens via the dictionary's line reader (expanded
    // form), then group by original tokens is impossible, so instead
    // use a dedicated token pass:
    // We implement it in the main print function using readWord.
    (void)line; (void)labels;
    vec.zero();
  }

  void computeHidden(const std::vector<int32_t>& input, Vector& hidden) const {
    hidden.zero();
    if (input.empty()) return;
    for (int32_t id : input) {
      if (id >= 0 && id < input_->size(0)) input_->addRowToVector(hidden, id);
    }
    hidden.mul(1.0f / (real)input.size());
  }

  bool predict(const std::vector<int32_t>& input, int32_t k, real threshold,
               std::vector<std::pair<real, int32_t>>& predictions,
               Loss::State& state) const {
    if (k == 0) {
      throw std::invalid_argument("k needs to be 1 or higher!");
    }
    if (args_->model != model_name::sup) {
      throw std::invalid_argument("Model needs to be supervised for prediction!");
    }
    if (input.empty()) return false;
    int32_t kk = k < 0 ? dict_->nlabels() : k;
    computeHidden(input, state.hidden);
    predictions.clear();
    loss_->predict(input, kk, threshold, predictions, state);
    // predictions currently holds log-probabilities in a heap;
    // sort by value descending and exponentiate.
    std::sort(predictions.begin(), predictions.end(),
              [](const std::pair<real,int32_t>& a, const std::pair<real,int32_t>& b) {
                return a.first > b.first;
              });
    for (auto& p : predictions) p.first = std::exp(p.first);
    return true;
  }
  bool predict(std::istream& in, int32_t k, real threshold,
               std::vector<std::pair<real, int32_t>>& predictions,
               Loss::State& state) {
    std::vector<int32_t> line;
    std::vector<int32_t> labels;
    dict_->getLine(in, line, labels);
    return predict(line, k, threshold, predictions, state);
  }

  real update(const std::vector<int32_t>& input, int32_t target, real lr,
              Loss::State& state) {
    if (input.empty()) return 0;
    computeHidden(input, state.hidden);
    state.grad.zero();
    real loss = loss_->forward(input, target, state, lr, true);
    loss_->backward(input, state, input_);
    state.loss += loss;
    state.nexamples++;
    return loss;
  }

  void saveVectors(const std::string& filename) {
    std::ofstream ofs(filename);
    if (!ofs.is_open()) {
      throw std::invalid_argument(filename + " cannot be opened for saving.");
    }
    ofs << dict_->nwords() << " " << args_->dim << std::endl;
    Vector vec(args_->dim);
    for (int32_t i = 0; i < dict_->nwords(); i++) {
      std::string word = dict_->getWord(i);
      getWordVector(vec, word);
      ofs << word << " " << vec << std::endl;
    }
  }
  void saveOutput(const std::string& filename) {
    std::ofstream ofs(filename);
    if (!ofs.is_open()) {
      throw std::invalid_argument(filename + " cannot be opened for saving.");
    }
    int32_t osize = args_->model == model_name::sup ? dict_->nlabels() : dict_->nwords();
    ofs << osize << " " << args_->dim << std::endl;
    Vector vec(args_->dim);
    for (int32_t i = 0; i < osize; i++) {
      std::string name = args_->model == model_name::sup ? dict_->getLabel(i)
                                                         : dict_->getWord(i);
      vec.zero();
      output_->addRowToVector(vec, i);
      ofs << name << " " << vec << std::endl;
    }
  }
  void saveModel(const std::string& filename) {
    std::ofstream ofs(filename, std::ofstream::binary);
    if (!ofs.is_open()) {
      throw std::invalid_argument(filename + " cannot be opened for saving.");
    }
    int32_t magic = FASTTEXT_FILEFORMAT_MAGIC_INT32;
    int32_t version = FASTTEXT_VERSION;
    ofs.write((char*)&magic, sizeof(magic));
    ofs.write((char*)&version, sizeof(version));
    args_->save(ofs);
    dict_->save(ofs);
    ofs.write((char*)&quant_, sizeof(quant_));
    input_->save(ofs);
    ofs.write((char*)&quantOut_, sizeof(quantOut_));
    output_->save(ofs);
  }
  void loadModel(const std::string& filename) {
    std::ifstream ifs(filename, std::ifstream::binary);
    if (!ifs.is_open()) {
      throw std::invalid_argument(filename + " cannot be opened for loading!");
    }
    loadModel(ifs, filename);
  }
  void loadModel(std::istream& in, const std::string& filename = "") {
    int32_t magic = 0;
    int32_t version = 0;
    in.read((char*)&magic, sizeof(magic));
    in.read((char*)&version, sizeof(version));
    if (magic != FASTTEXT_FILEFORMAT_MAGIC_INT32 || version > 12) {
      throw std::invalid_argument(filename + " has wrong file format!");
    }
    args_ = std::make_shared<Args>();
    args_->load(in);
    if (version == 11 && args_->model == model_name::sup) {
      args_->maxn = 0;
    }
    dict_ = std::make_shared<Dictionary>(args_);
    dict_->load(in);
    bool quantIn = false;
    in.read((char*)&quantIn, sizeof(quantIn));
    quant_ = quantIn;
    if (quant_) {
      auto qm = std::make_shared<QuantMatrix>();
      qm->load(in);
      input_ = qm;
    } else {
      auto dm = std::make_shared<DenseMatrix>();
      dm->load(in);
      input_ = dm;
    }
    bool qout = false;
    in.read((char*)&qout, sizeof(qout));
    quantOut_ = qout;
    if (quantOut_) {
      auto qm = std::make_shared<QuantMatrix>();
      qm->load(in);
      output_ = qm;
    } else {
      auto dm = std::make_shared<DenseMatrix>();
      dm->load(in);
      output_ = dm;
    }
    createLoss();
    wordVectors_.reset();
  }

  void loadPretrained(const std::string& filename) {
    std::ifstream in(filename);
    if (!in.is_open()) {
      throw std::invalid_argument(filename + " cannot be opened for loading!");
    }
    int32_t nvec = 0;
    int32_t dim = 0;
    in >> nvec >> dim;
    if (dim != args_->dim) {
      throw std::invalid_argument(
          "Dimension of pretrained vectors (" + std::to_string(dim) +
          ") does not match dimension (" + std::to_string(args_->dim) + ")!");
    }
    pretrainedRows_.clear();
    std::string word;
    // Words from the pretrained file are added to the dictionary in
    // file order (appended after existing words, before labels are
    // repositioned by the insert step below as in the reference).
    // We first read all rows.
    std::vector<std::pair<std::string, std::vector<real>>> rows;
    for (int32_t i = 0; i < nvec; i++) {
      if (!(in >> word)) break;
      std::vector<real> v(args_->dim);
      for (int32_t j = 0; j < args_->dim; j++) in >> v[j];
      rows.emplace_back(word, v);
    }
    // Expand dictionary: existing entries keep order; new words are
    // placed after all existing words and before labels.
    // Split current entries into words / labels.
    std::vector<Entry> words;
    std::vector<Entry> labels;
    for (auto& e : dict_->entries_) {
      if (e.type == entry_type::word) words.push_back(e);
      else labels.push_back(e);
    }
    for (auto& kv : rows) {
      pretrainedRows_[kv.first] = kv.second;
