    dict_->nlabels_ = (int32_t)labels.size();
    dict_->size_ = dict_->nwords_ + dict_->nlabels_;
    dict_->words_.clear();
    for (int32_t i = 0; i < dict_->size_; i++) dict_->words_[dict_->entries_[i].word] = i;
    dict_->initTableDiscard();
    dict_->initNgrams();
  }

  // training is implemented further below
  void train(const std::shared_ptr<Args>& args);
  void startThreads();
  void trainThread(int32_t threadId);
  void supervised(Loss::State& state, const std::vector<int32_t>& line,
