  in.seekg(0, std::ios::end);
  std::streampos fileSize = in.tellg();
  in.seekg(0, std::ios::beg);
  auto seekToStart = [&]() {
    in.clear();
    if (args_->thread > 1 && fileSize > 0) {
      std::streamoff pos = (std::streamoff)((int64_t)fileSize * threadId / args_->thread);
      in.seekg(pos);
      if (threadId > 0) {
        std::string dummy;
        std::getline(in, dummy);
      }
    } else {
      in.seekg(0);
    }
  };
  seekToStart();

  int32_t osize = args_->model == model_name::sup ? dict_->nlabels() : dict_->nwords();
  Loss::State state(args_->dim, osize, (unsigned int)(args_->seed + threadId));

  // Slice-wise input initialization for freshly created dense input
  // matrices.  A flag on the FastText object (set only for the
  // ordinary train command, see below) controls this via a thread
  // local check encoded in tokenCount_ state: we use a member set
  // by train().
  // (Implemented in startThreads through initInputSlice_.)

  int64_t ntokensTotal = dict_->ntokens();
  int64_t totalToProcess = (int64_t)args_->epoch * ntokensTotal;
  int64_t localTokens = 0;
  real lr = (real)args_->lr;
  std::vector<int32_t> line;
  std::vector<int32_t> labels;

  while (tokenCount_.load() < totalToProcess) {
    // peek for EOF and restart this thread's partition
    if (in.peek() == std::ifstream::traits_type::eof()) {
      seekToStart();
      if (in.peek() == std::ifstream::traits_type::eof()) break;
    }
    int32_t ntokens = 0;
    if (args_->model == model_name::sup) {
      ntokens = dict_->getLine(in, line, labels);
      localTokens += ntokens;
      supervised(state, line, labels, lr);
    } else if (args_->model == model_name::cbow) {
      ntokens = dict_->getLine(in, line, state.rng);
      localTokens += ntokens;
      cbow(state, line, lr);
    } else {
      ntokens = dict_->getLine(in, line, state.rng);
      localTokens += ntokens;
      skipgram(state, line, lr);
    }
    if (ntokens == 0) {
      // avoid a busy loop at EOF
      in.clear();
      seekToStart();
      continue;
    }
    if (localTokens >= args_->lrUpdateRate) {
      tokenCount_ += localTokens;
      localTokens = 0;
      real progressLR = totalToProcess > 0
                            ? (real)tokenCount_.load() / (real)totalToProcess
                            : 1.0f;
      lr = (real)args_->lr * (1.0f - progressLR);
      if (lr < args_->lr * 0.0001) lr = 0;
    }
