        std::this_thread::sleep_for(std::chrono::milliseconds(100));
        if (tokenCount_.load() >= total) break;
        real avg = nexAgg_.load() > 0 ? lossAgg_.load() / (real)nexAgg_.load() : 0;
        // Note: per-thread losses are only aggregated at thread end
        // in this implementation, so intermediate avg.loss may lag;
        // final values are exact.
        real progressLR = total > 0 ? (real)tokenCount_.load() / (real)total : 1;
        real lrNow = (real)args_->lr * (1.0f - progressLR);
        printInfo(std::cerr, false, tokenCount_.load(), avg, lrNow);
      }
    }
    for (auto& t : threads) t.join();
  }
  if (args_->verbose > 0) {
    real avg = nexAgg_.load() > 0 ? lossAgg_.load() / (real)nexAgg_.load()
                                   : (real)(0.0 / 0.0);
    int64_t shownTokens = (int64_t)args_->epoch * dict_->ntokens();
    if (shownTokens < 0) shownTokens = 0;
    // words/sec in the reference uses the nominal total
    printInfo(std::cerr, true, shownTokens, avg, 0);
  }
}

inline void FastText::train(const std::shared_ptr<Args>& args) {
  args_ = args;
  auto start = std::chrono::steady_clock::now();
  trainStart_ = start;
  if (args_->input == "-") {
    throw std::invalid_argument("Cannot use stdin for training!");
  }
  dict_ = std::make_shared<Dictionary>(args_);
  {
    std::ifstream in(args_->input, std::ios::binary);
    if (!in.is_open()) {
      throw std::invalid_argument(args_->input + " cannot be opened for training!");
    }
    in.exceptions(std::ifstream::badbit);
    dict_->readFromInput(in);
  }
  if (args_->verbose > 0) {
    std::cerr << "\rRead " << dict_->ntokens() / 1000000 << "M words" << std::endl;
    std::cerr << "Number of words:  " << dict_->nwords() << std::endl;
    std::cerr << "Number of labels: " << dict_->nlabels() << std::endl;
  }
  if (dict_->size() == 0) {
    throw std::invalid_argument("Empty vocabulary. Try a smaller -minCount value.");
  }
  // Load pretrained vectors (expands dictionary) if requested
  pretrainedRows_.clear();
  if (!args_->pretrainedVectors.empty()) {
    loadPretrained(args_->pretrainedVectors);
  }
  // Input / output matrices
  if (args_->maxn == 0 && args_->wordNgrams <= 1) {
    args_->bucket = 0;
  }
  int64_t inputRows = (int64_t)dict_->nwords() + args_->bucket;
  auto inputDense = std::make_shared<DenseMatrix>(inputRows, args_->dim);
  input_ = inputDense;
  int32_t osize = args_->model == model_name::sup ? dict_->nlabels() : dict_->nwords();
  auto outputDense = std::make_shared<DenseMatrix>(osize, args_->dim);
  outputDense->zero();
  output_ = outputDense;
  quant_ = false;
  quantOut_ = false;
  createLoss();
  lossAgg_ = 0;
  nexAgg_ = 0;

  // Input slice initialization runs inside the training threads in
  // the reference.  We reproduce the resulting matrix here, before
  // training updates begin, by applying one slice per configured
  // training thread (only for a positive thread count; situations
  // with thread <= 0 fall through to the same failure modes in the
  // thread launcher below).
  if (args_->thread > 0 && args_->dim > 0) {
    for (int32_t t = 0; t < args_->thread; t++) {
      inputDense->uniform(1.0f / args_->dim, (unsigned int)args_->seed, t);
    }
  } else if (args_->thread > 0 && args_->dim == 0) {
    // zero-dimensional matrices need no filling
  }
  // Apply pretrained rows in full, after slice initialization.
  if (!pretrainedRows_.empty()) {
    for (auto& kv : pretrainedRows_) {
      int32_t id = dict_->getId(kv.first);
      if (id >= 0 && id < inputRows) {
        for (int32_t j = 0; j < args_->dim; j++) inputDense->at(id, j) = kv.second[j];
      }
    }
  }

  startThreads();
}

inline std::vector<int32_t> FastText::selectEmbeddings(int32_t cutoff) const {
  auto dense = std::dynamic_pointer_cast<DenseMatrix>(input_);
  std::vector<int32_t> selected;
  for (int32_t i = 0; i < dict_->nwords(); i++) selected.push_back(i);
  if (cutoff <= dict_->nwords() || !dense) return selected;
  std::vector<std::pair<real, int32_t>> norms;
  for (int64_t i = dict_->nwords(); i < dense->m_; i++) {
    norms.emplace_back(dense->l2NormRow(i), (int32_t)i);
  }
  std::sort(norms.begin(), norms.end(),
            [](const std::pair<real,int32_t>& a, const std::pair<real,int32_t>& b) {
              return a.first > b.first;
            });
  int32_t keep = std::min<int32_t>(cutoff - dict_->nwords(), (int32_t)norms.size());
  for (int32_t i = 0; i < keep; i++) selected.push_back(norms[i].second);
  return selected;
}

inline void FastText::quantize(const std::shared_ptr<Args>& qargs) {
  auto denseIn = std::dynamic_pointer_cast<DenseMatrix>(input_);
  if (!denseIn) return;
  std::shared_ptr<DenseMatrix> selected = denseIn;
  if (qargs->cutoff > 0 && qargs->cutoff < denseIn->m_) {
    auto sel = selectEmbeddings(qargs->cutoff);
    auto ns = std::make_shared<DenseMatrix>((int64_t)sel.size(), denseIn->n_);
    for (size_t r = 0; r < sel.size(); r++) {
      for (int64_t j = 0; j < denseIn->n_; j++) ns->at(r, j) = denseIn->at(sel[r], j);
    }
    dict_->prune(sel);
    selected = ns;
    input_ = ns;
    if (qargs->retrain) {
      // Fine-tune the pruned embeddings on the quantization input.
      auto savedInput = args_->input;
      auto savedOutput = args_->output;
      // Temporarily train with the quantize arguments' file/epoch:
      // the reference re-runs supervised/unsupervised training on
      // qargs->input with qargs training hyper-parameters.
      auto trainArgs = std::make_shared<Args>(*args_);
      trainArgs->input = qargs->input;
      trainArgs->output = qargs->output;
      trainArgs->epoch = qargs->epoch;
      trainArgs->lr = qargs->lr;
      trainArgs->thread = qargs->thread;
      trainArgs->verbose = qargs->verbose;
      auto mainArgs = args_;
      args_ = trainArgs;
      createLoss();
      lossAgg_ = 0; nexAgg_ = 0;
      startThreads();
      args_ = mainArgs;
      createLoss();
      (void)savedInput; (void)savedOutput;
    }
  }
  auto qm = std::make_shared<QuantMatrix>(std::move(*selected), qargs->dsub, qargs->qnorm);
  input_ = qm;
  quant_ = true;
  if (qargs->qout) {
    auto denseOut = std::dynamic_pointer_cast<DenseMatrix>(output_);
    if (denseOut) {
      auto qo = std::make_shared<QuantMatrix>(std::move(*denseOut), qargs->dsub, qargs->qnorm);
      output_ = qo;
      quantOut_ = true;
    }
  }
  createLoss();
}

inline void FastText::precomputeWordVectors() {
  if (wordVectors_) return;
  wordVectors_ = std::make_shared<DenseMatrix>(dict_->nwords(), args_->dim);
  Vector vec(args_->dim);
  for (int32_t i = 0; i < dict_->nwords(); i++) {
    getWordVector(vec, dict_->getWord(i));
    real norm = vec.norm();
    if (norm > 0) vec.mul(1.0f / norm);
    for (int32_t j = 0; j < args_->dim; j++) wordVectors_->at(i, j) = vec[j];
  }
}
inline std::vector<std::pair<real, std::string>> FastText::getNearestNeighbors(
    const Vector& query, int32_t k, const std::set<std::string>& exclude) {
  precomputeWordVectors();
  std::vector<std::pair<real, std::string>> results;
  // max-heap by value maintained at size k via min-heap on neg value:
  // use a vector as a heap of candidates sorted at the end for simplicity
  std::vector<std::pair<real, std::string>> all;
  for (int32_t i = 0; i < dict_->nwords(); i++) {
    std::string w = dict_->getWord(i);
    if (exclude.count(w)) continue;
    real v = wordVectors_->dotRow(query, i);
    all.emplace_back(v, w);
  }
  int32_t kk = k < 0 ? (int32_t)all.size() : k;
  std::sort(all.begin(), all.end(),
            [](const std::pair<real,std::string>& a, const std::pair<real,std::string>& b) {
              if (a.first != b.first) return a.first > b.first;
              return a.second > b.second;
            });
  if ((int32_t)all.size() > kk) all.resize(std::max(kk, 0));
  return all;
}

