static void trainCommand(const std::vector<std::string>& args) {
  auto a = std::make_shared<Args>();
  a->parseArgs(args);
  FastText ft;
  // Autotune is handled in a dedicated path
  if (!a->autotuneValidationFile.empty()) {
    // See autotuneTrain below (declared via lambda dispatch in main)
  }
  ft.train(a);
  ft.saveModel(a->output + ".bin");
  ft.saveVectors(a->output + ".vec");
  if (a->saveOutput) ft.saveOutput(a->output + ".output");
}

// Autotune: random search over a small hyper-parameter space,
// evaluating on the validation file with the requested metric.
static double evalModelOnFile(FastText& ft, const std::string& file,
                              const std::shared_ptr<Args>& a) {
  std::ifstream ifs(file);
  if (!ifs.is_open()) {
    throw std::invalid_argument(file + " cannot be opened for training!");
  }
  Meter meter(ft.getDictionary()->nlabels());
  // runTest expects seekable stream; files are seekable.
  runTest(ft, ifs, a->autotunePredictions, 0.0f, meter);
  std::string wantLabel = a->autotuneMetricLabel();
  if (!wantLabel.empty()) {
    for (int32_t i = 0; i < ft.getDictionary()->nlabels(); i++) {
      if (ft.getDictionary()->getLabel(i) == wantLabel ||
          ft.getDictionary()->getLabel(i) == a->label + wantLabel) {
        auto& st = meter.perLabel[i];
        double p = st.predicted ? (double)st.correct / st.predicted : 0;
        double r = st.gold ? (double)st.correct / st.gold : 0;
        return (p + r) > 0 ? 2 * p * r / (p + r) : 0;
      }
    }
    return 0;
  }
  double p = meter.npredictions ? (double)meter.ncorrect / meter.npredictions : 0;
  double r = meter.nlabelsTotal ? (double)meter.ncorrect / meter.nlabelsTotal : 0;
  return (p + r) > 0 ? 2 * p * r / (p + r) : 0;
}

static bool autotuneTrain(const std::vector<std::string>& argsVec) {
  auto base = std::make_shared<Args>();
  base->parseArgs(argsVec);
  if (base->autotuneValidationFile.empty()) return false;
  // Warnings for manually set parameters (order observed: maxn, minn,
  // bucket, dim, then others).  Emit warnings for the commonly
  // reported ones in that relative order.
  auto warn = [&](const char* flag, const char* name) {
    if (base->manuallySet.count(flag)) {
      std::cerr << "Warning : " << name
                << " is manually set to a specific value. It will not be automatically optimized." << std::endl;
    }
  };
  warn("-maxn", "maxn");
  warn("-minn", "minn");
  warn("-bucket", "bucket");
  warn("-dim", "dim");
  warn("-epoch", "epoch");
  warn("-lr", "lr");
  warn("-wordNgrams", "wordNgrams");
  warn("-loss", "loss");
  warn("-minCount", "minCount");
  warn("-minCountLabel", "minCountLabel");
  warn("-neg", "neg");
  warn("-t", "t");
  std::cerr << std::endl;

  auto start = std::chrono::steady_clock::now();
  double bestScore = -1;
  std::shared_ptr<Args> bestArgs = std::make_shared<Args>(*base);
  int32_t trials = 0;
  std::minstd_rand rng(0);
  // Candidate space (only varying args not manually set)
  while (true) {
    double elapsed = std::chrono::duration_cast<std::chrono::milliseconds>(
                         std::chrono::steady_clock::now() - start).count() / 1000.0;
    if (elapsed >= base->autotuneDuration) break;
    auto cand = std::make_shared<Args>(*base);
    cand->verbose = 0;
    cand->autotuneValidationFile = "";
    if (!base->manuallySet.count("-lr")) {
      std::uniform_real_distribution<> d(0.01, 1.0);
      cand->lr = d(rng);
    }
    if (!base->manuallySet.count("-epoch")) {
      std::uniform_int_distribution<int32_t> d(1, 50);
      cand->epoch = d(rng);
    }
    if (!base->manuallySet.count("-dim")) {
      std::uniform_int_distribution<int32_t> d(1, 20);
      cand->dim = d(rng) * 10;
    }
    if (!base->manuallySet.count("-wordNgrams")) {
      std::uniform_int_distribution<int32_t> d(1, 5);
      cand->wordNgrams = d(rng);
    }
    if (!base->manuallySet.count("-minn") && !base->manuallySet.count("-maxn") &&
        cand->model == model_name::sup) {
      std::uniform_int_distribution<int32_t> d(0, 6);
      cand->minn = d(rng);
      cand->maxn = cand->minn == 0 ? 0 : cand->minn + (int32_t)std::uniform_int_distribution<int32_t>(0, 3)(rng);
      if (cand->maxn > 0 && !base->manuallySet.count("-bucket")) cand->bucket = 2000000;
    }
    trials++;
    double score = -1;
    try {
      FastText ft;
      ft.train(cand);
      score = evalModelOnFile(ft, base->autotuneValidationFile, base);
    } catch (...) {
      score = -1;
    }
    if (score > bestScore) {
      bestScore = score;
      bestArgs = cand;
    }
    double elapsed2 = std::chrono::duration_cast<std::chrono::milliseconds>(
                          std::chrono::steady_clock::now() - start).count() / 1000.0;
    double progress = base->autotuneDuration > 0 ? elapsed2 / base->autotuneDuration : 1.0;
    if (progress > 1) progress = 1;
    int64_t eta = (int64_t)std::max(0.0, base->autotuneDuration - elapsed2);
    std::cerr << "\rProgress:" << std::fixed << std::setprecision(1) << std::setw(6)
              << progress * 100 << "%"
              << " Trials:" << std::setw(5) << trials
              << " Best score:" << std::setprecision(6) << std::setw(10)
              << std::max(bestScore, 0.0)
              << " ETA:" << std::setw(4) << (eta / 3600) << "h" << std::setw(2)
              << ((eta % 3600) / 60) << "m" << std::setw(2) << (eta % 60) << "s"
              << std::endl;
    std::cerr.unsetf(std::ios::floatfield);
    std::cerr << std::setprecision(6);
    if (elapsed2 >= base->autotuneDuration) break;
  }
  std::cerr << "Training again with best arguments" << std::endl;
  bestArgs->verbose = base->verbose;
  bestArgs->autotuneValidationFile = "";
  FastText ft;
  ft.train(bestArgs);
  if (!base->autotuneModelSize.empty()) {
    // Quantize to respect model size in a best-effort fashion
    ft.quantize(bestArgs);
    ft.saveModel(bestArgs->output + ".ftz");
  } else {
    ft.saveModel(bestArgs->output + ".bin");
  }
  ft.saveVectors(bestArgs->output + ".vec");
  if (bestArgs->saveOutput) ft.saveOutput(bestArgs->output + ".output");
  return true;
}

