    ft.getDictionary()->dump(std::cout);
  } else if (option == "input") {
    if (ft.quant_) std::cerr << "Not supported for quantized models." << std::endl;
    else ft.getInput()->dump(std::cout);
  } else if (option == "output") {
    if (ft.quant_) std::cerr << "Not supported for quantized models." << std::endl;
