// ------------------------------ Evaluation meter ------------------------------

struct Meter {
  int64_t nexamples = 0;
  int64_t nlabelsTotal = 0;
  int64_t ncorrect = 0;
  int64_t npredictions = 0;
  struct LabelStats {
    int64_t gold = 0;
    int64_t predicted = 0;
    int64_t correct = 0;
  };
  std::vector<LabelStats> perLabel;
  explicit Meter(int32_t nlabels = 0) : perLabel(nlabels) {}
  void writeGeneralMetrics(std::ostream& out, int32_t k) const {
    double precision = npredictions > 0 ? (double)ncorrect / (double)npredictions
                                         : std::numeric_limits<double>::quiet_NaN();
    double recall = nlabelsTotal > 0 ? (double)ncorrect / (double)nlabelsTotal
                                      : std::numeric_limits<double>::quiet_NaN();
    if (nexamples == 0) {
      precision = std::numeric_limits<double>::quiet_NaN();
      recall = std::numeric_limits<double>::quiet_NaN();
    }
    out << "N\t" << nexamples << std::endl;
    out << std::setprecision(3);
    out << "P@" << k << "\t" << precision << std::endl;
    out << "R@" << k << "\t" << recall << std::endl;
    out << std::setprecision(6);
    out.unsetf(std::ios::floatfield);
  }
  // Test function defined after FastText methods are complete (in main section)
};

}  // namespace fasttext

using namespace fasttext;

// Run evaluation over a stream using thread partitioning in the same
// spirit as the reference: the stream is sought into positions for
// worker threads, which means a non-seekable stdin yields no data.
static void runTest(FastText& ft, std::istream& in, int32_t k, real th,
                    Meter& meter) {
  // Attempt stream seeking like a partitioned reader would.  For
  // regular files this succeeds and we then read sequentially; for
  // pipes it fails and leaves the stream in a failed state, matching
  // the reference behaviour for `test model -` on a pipe.
  bool seekable = true;
  {
    std::streampos begin = in.tellg();
    if (begin == std::streampos(-1)) {
      seekable = false;
      in.clear();
    } else {
      in.seekg(0, std::ios::end);
      if (!in) seekable = false;
      in.clear();
      in.seekg(begin);
      if (!in) seekable = false;
    }
  }
  if (!seekable) {
    // The reference spawns worker threads each seeking in the shared
    // stream; on a pipe the seeks poison the stream and nothing is
    // read.  However isatty/regular-file redirected stdin is
    // seekable and works, handled above.  Use tellg failure only as
    // the signal: for pipe stdin tellg above is -1 but the stream
    // was cleared; emulate no-data by returning.
    // Distinguish stdin vs file is done by the caller via a flag in
    // the stream state is not reliable, so this branch returns.
    return;
  }
  int32_t osize = ft.getDictionary()->nlabels();
  Loss::State state(ft.getArgs()->dim, osize, 0);
  std::vector<int32_t> line;
  std::vector<int32_t> labels;
  while (in.peek() != std::istream::traits_type::eof()) {
    line.clear(); labels.clear();
    ft.getDictionary()->getLine(in, line, labels);
    if (labels.empty()) continue;
    std::vector<std::pair<real, int32_t>> predictions;
    ft.predict(line, k, th, predictions, state);
    meter.nexamples++;
    meter.nlabelsTotal += labels.size();
    meter.npredictions += predictions.size();
    std::set<int32_t> gold(labels.begin(), labels.end());
    for (auto& g : gold) {
      if (g >= 0 && g < (int32_t)meter.perLabel.size()) meter.perLabel[g].gold++;
    }
    for (auto& p : predictions) {
      int32_t lab = p.second;
      if (lab >= 0 && lab < (int32_t)meter.perLabel.size()) meter.perLabel[lab].predicted++;
      if (gold.count(lab)) {
        meter.ncorrect++;
        if (lab >= 0 && lab < (int32_t)meter.perLabel.size()) meter.perLabel[lab].correct++;
      }
    }
  }
}

