      << "  predict                 predict most likely labels" << std::endl
      << "  predict-prob            predict most likely labels with probabilities" << std::endl
      << "  skipgram                train a skipgram model" << std::endl
      << "  cbow                    train a cbow model" << std::endl
      << "  print-word-vectors      print word vectors given a trained model" << std::endl
      << "  print-sentence-vectors  print sentence vectors given a trained model" << std::endl
