static void printNgramsCommand(const std::vector<std::string>& args) {
  if (args.size() != 3) {
    std::cerr << "usage: fasttext print-ngrams <model> <word>" << std::endl
              << std::endl
              << "  <model>      model filename" << std::endl
              << "  <word>       word to print" << std::endl
              << std::endl;
    std::exit(EXIT_FAILURE);
  }
  FastText ft;
  ft.loadModel(args[1]);
  std::string word = args[2];
  std::vector<std::string> ngrams;
  std::vector<int32_t> ids;
  ft.getDictionary()->getSubwords(word, ngrams, ids);
  for (size_t i = 0; i < ngrams.size(); i++) {
    Vector vec(ft.getArgs()->dim);
    // Note: the reference does not zero this vector before adding
    // the row (uninitialised contents show through in its output).
    if (ids[i] >= 0 && ids[i] < ft.getInput()->size(0)) {
      ft.getInput()->addRowToVector(vec, ids[i]);
    }
    std::cout << ngrams[i] << " " << vec << std::endl;
  }
}
static void predictCommand(const std::vector<std::string>& args, bool prob) {
  if (args.size() < 3 || args.size() > 5) {
    std::cerr << "usage: fasttext predict[-prob] <model> <test-data> [<k>] [<th>]" << std::endl
              << std::endl
              << "  <model>      model filename" << std::endl
              << "  <test-data>  test data filename (if -, read from stdin)" << std::endl
              << "  <k>          (optional; 1 by default) predict top k labels" << std::endl
              << "  <th>         (optional; 0.0 by default) probability threshold" << std::endl
              << std::endl;
    std::exit(EXIT_FAILURE);
  }
  int32_t k = 1;
  real th = 0.0f;
  if (args.size() > 3) k = std::stoi(args[3]);
  if (args.size() > 4) th = std::stof(args[4]);
  FastText ft;
  ft.loadModel(args[1]);
  std::ifstream ifs;
  std::istream* in = &std::cin;
  if (args[2] != "-") {
    ifs.open(args[2]);
    if (!ifs.is_open()) {
      std::cerr << "Input file cannot be opened!" << std::endl;
      std::exit(EXIT_FAILURE);
    }
    in = &ifs;
  }
  Loss::State state(ft.getArgs()->dim, ft.getDictionary()->nlabels(), 0);
  std::vector<std::pair<real, int32_t>> predictions;
  while (in->peek() != std::istream::traits_type::eof()) {
    predictions.clear();
    ft.predict(*in, k, th, predictions, state);
    bool first = true;
    for (auto& p : predictions) {
      if (!first) std::cout << " ";
      first = false;
      std::cout << ft.getDictionary()->getLabel(p.second);
      if (prob) std::cout << " " << p.first;
    }
    std::cout << std::endl;
  }
}
static void testCommand(const std::vector<std::string>& args, bool perLabel) {
  if (args.size() < 3 || args.size() > 5) {
    if (perLabel) {
      std::cerr << "usage: fasttext test-label <model> <test-data> [<k>] [<th>]" << std::endl
                << std::endl
                << "  <model>      model filename" << std::endl
                << "  <test-data>  test data filename" << std::endl
                << "  <k>          (optional; 1 by default) predict top k labels" << std::endl
                << "  <th>         (optional; 0.0 by default) probability threshold" << std::endl
                << std::endl;
    } else {
      std::cerr << "usage: fasttext test <model> <test-data> [<k>] [<th>]" << std::endl
                << std::endl
                << "  <model>      model filename" << std::endl
                << "  <test-data>  test data filename (if -, read from stdin)" << std::endl
                << "  <k>          (optional; 1 by default) predict top k labels" << std::endl
                << "  <th>         (optional; 0.0 by default) probability threshold" << std::endl
                << std::endl;
    }
    std::exit(EXIT_FAILURE);
  }
  int32_t k = 1;
  real th = 0.0f;
  if (args.size() > 3) k = std::stoi(args[3]);
  if (args.size() > 4) th = std::stof(args[4]);
  if (k == 0) throw std::invalid_argument("k needs to be 1 or higher!");
  FastText ft;
  ft.loadModel(args[1]);
  std::ifstream ifs;
  std::istream* in = &std::cin;
  if (args[2] != "-") {
    ifs.open(args[2]);
    if (!ifs.is_open()) {
      std::cerr << "Test file cannot be opened!" << std::endl;
      std::exit(EXIT_FAILURE);
    }
    in = &ifs;
  }
  Meter meter(ft.getDictionary()->nlabels());
  runTest(ft, *in, k, th, meter);
  if (perLabel) {
    for (int32_t i = 0; i < ft.getDictionary()->nlabels(); i++) {
      auto& st = meter.perLabel[i];
      auto fmt = [](double num, int64_t den, std::ostream& out) {
        if (den == 0) out << "--------";
        else out << std::fixed << std::setprecision(6) << (num / (double)den);
        out.unsetf(std::ios::floatfield);
        out << std::setprecision(6);
      };
      std::cout << "F1-Score : ";
      {
        double p = st.predicted ? (double)st.correct / st.predicted : 0;
        double r = st.gold ? (double)st.correct / st.gold : 0;
        if (st.predicted == 0 || st.gold == 0) std::cout << "--------";
        else {
          double f1 = (p + r) > 0 ? 2 * p * r / (p + r) : 0;
          std::cout << std::fixed << std::setprecision(6) << f1;
          std::cout.unsetf(std::ios::floatfield);
          std::cout << std::setprecision(6);
        }
      }
      std::cout << "  Precision : ";
      fmt((double)st.correct, st.predicted, std::cout);
      // fmt printed value already divided; adjust: recompute simpler below
      std::cout << "  Recall : ";
      // Re-emit correctly: the above Precision used fmt(num,den) which printed num/den
      fmt((double)st.correct, st.gold, std::cout);
      std::cout << "   " << ft.getDictionary()->getLabel(i) << std::endl;
    }
    // General metrics follow the fixed formatting state left by labels
    double precision = meter.npredictions ? (double)meter.ncorrect / meter.npredictions
                                            : std::numeric_limits<double>::quiet_NaN();
    double recall = meter.nlabelsTotal ? (double)meter.ncorrect / meter.nlabelsTotal
                                        : std::numeric_limits<double>::quiet_NaN();
    if (meter.nexamples == 0) {
      precision = std::numeric_limits<double>::quiet_NaN();
      recall = std::numeric_limits<double>::quiet_NaN();
    }
    std::cout << "N\t" << meter.nexamples << std::endl;
    std::cout << std::fixed << std::setprecision(3);
    std::cout << "P@" << k << "\t" << precision << std::endl;
    std::cout << "R@" << k << "\t" << recall << std::endl;
    std::cout.unsetf(std::ios::floatfield);
  } else {
    meter.writeGeneralMetrics(std::cout, k);
  }
}
static void nnCommand(const std::vector<std::string>& args) {
  if (args.size() < 2 || args.size() > 3) {
    std::cout << "usage: fasttext nn <model> <k>" << std::endl
              << std::endl
              << "  <model>      model filename" << std::endl
              << "  <k>          (optional; 10 by default) predict top k labels" << std::endl
              << std::endl;
    std::exit(EXIT_FAILURE);
  }
  int32_t k = 10;
  if (args.size() > 2) k = std::stoi(args[2]);
  FastText ft;
  ft.loadModel(args[1]);
  ft.precomputeWordVectors();
  std::string word;
  while (true) {
    std::cout << "Query word? " << std::flush;
    if (!(std::cin >> word)) break;
    Vector vec(ft.getArgs()->dim);
    ft.getWordVector(vec, word);
    real norm = vec.norm();
    if (norm > 0) vec.mul(1.0f / norm);
    int32_t kk = k < 0 ? 10 : k;
    auto results = ft.getNearestNeighbors(vec, kk, {word});
    for (auto& r : results) {
      std::cout << r.second << " " << r.first << std::endl;
    }
  }
}
static void analogiesCommand(const std::vector<std::string>& args) {
  if (args.size() < 2 || args.size() > 3) {
    std::cout << "usage: fasttext analogies <model> <k>" << std::endl
              << std::endl
              << "  <model>      model filename" << std::endl
              << "  <k>          (optional; 10 by default) predict top k labels" << std::endl
              << std::endl;
    std::exit(EXIT_FAILURE);
  }
  int32_t k = 10;
  if (args.size() > 2) k = std::stoi(args[2]);
  std::cout << "Loading model " << args[1] << std::endl;
  FastText ft;
  ft.loadModel(args[1]);
  ft.precomputeWordVectors();
  std::string a, b, c;
  while (true) {
    std::cout << "Query triplet (A - B + C)? " << std::flush;
    std::cin >> a >> b >> c;
    Vector va(ft.getArgs()->dim), vb(ft.getArgs()->dim), vc(ft.getArgs()->dim);
    ft.getWordVector(va, a);
    ft.getWordVector(vb, b);
    ft.getWordVector(vc, c);
    auto normVec = [](Vector& v) {
      real n = v.norm();
      if (n > 0) v.mul(1.0f / n);
    };
    normVec(va); normVec(vb); normVec(vc);
    Vector q(ft.getArgs()->dim);
    q.zero();
    for (int32_t i = 0; i < ft.getArgs()->dim; i++) q[i] = va[i] - vb[i] + vc[i];
    normVec(q);
    int32_t kk = k < 0 ? 10 : k;
    auto results = ft.getNearestNeighbors(q, kk, {a, b, c});
    for (auto& r : results) {
      std::cout << r.second << " " << r.first << std::endl;
    }
  }
}
static void dumpCommand(const std::vector<std::string>& args) {
  auto usage = []() {
    std::cout << "usage: fasttext dump <model> <option>" << std::endl
              << std::endl
              << "  <model>      model filename" << std::endl
              << "  <option>     option from args,dict,input,output" << std::endl;
    std::exit(EXIT_FAILURE);
  };
  if (args.size() < 3) usage();
  std::string option = args[2];
  if (option != "args" && option != "dict" && option != "input" && option != "output") {
    usage();
  }
  FastText ft;
  ft.loadModel(args[1]);
  if (option == "args") {
    ft.getArgs()->dump(std::cout);
  } else if (option == "dict") {
    ft.getDictionary()->dump(std::cout);
  } else if (option == "input") {
    if (ft.quant_) std::cerr << "Not supported for quantized models." << std::endl;
    else ft.getInput()->dump(std::cout);
  } else if (option == "output") {
    if (ft.quant_) std::cerr << "Not supported for quantized models." << std::endl;
    else ft.getOutput()->dump(std::cout);
  }
}

int main(int argc, char** argv) {
  std::vector<std::string> args(argv, argv + argc);
  if (args.size() < 2) {
    printUsage();
    return EXIT_FAILURE;
  }
  std::string command = args[1];
  std::vector<std::string> subargs(args.begin() + 1, args.end());
  if (command == "supervised" || command == "skipgram" || command == "cbow") {
    if (!autotuneTrain(subargs)) {
      trainCommand(subargs);
    }
  } else if (command == "quantize") {
    quantizeCommand(subargs);
  } else if (command == "test") {
    testCommand(subargs, false);
  } else if (command == "test-label") {
    testCommand(subargs, true);
  } else if (command == "predict") {
    predictCommand(subargs, false);
  } else if (command == "predict-prob") {
    predictCommand(subargs, true);
  } else if (command == "print-word-vectors") {
    printWordVectorsCommand(subargs);
  } else if (command == "print-sentence-vectors") {
    printSentenceVectorsCommand(subargs);
  } else if (command == "print-ngrams") {
    printNgramsCommand(subargs);
  } else if (command == "nn") {
    nnCommand(subargs);
  } else if (command == "analogies") {
    analogiesCommand(subargs);
  } else if (command == "dump") {
    dumpCommand(subargs);
  } else {
    printUsage();
    return EXIT_FAILURE;
  }
  return EXIT_SUCCESS;
}
