import math
init=[[1.,0.],[0.,1.],[1.,1.]]; line=[0,1,2]; contexts={0:[1],1:[0,2],2:[1]}
def sim(passes,hidden_mode,input_scale,lr_sched='const'):
 W=[r[:] for r in init]; O=[[0.,0.] for _ in range(3)]; losses=[]
 for p in range(passes):
  lr=1.0 if lr_sched=='const' else 1.0
  for center in line:
   bow=contexts[center]
   h=[sum(W[i][j] for i in bow)/len(bow) if hidden_mode=='avg' else sum(W[i][j] for i in bow) for j in range(2)]
   scores=[sum(O[i][j]*h[j] for j in range(2)) for i in range(3)]; mx=max(scores); ex=[math.exp(x-mx) for x in scores]; probs=[x/sum(ex) for x in ex]; losses.append(-math.log(probs[center]))
   alphas=[lr*((1.0 if i==center else 0)-probs[i]) for i in range(3)]
   grad=[sum(alphas[i]*O[i][j] for i in range(3)) for j in range(2)]
   for i in range(3):
    for j in range(2): O[i][j]+=alphas[i]*h[j]
   scale=1/len(bow) if input_scale=='div' else 1
   for i in bow:
    for j in range(2): W[i][j]+=scale*grad[j]
 return W,O,sum(losses)/len(losses)
for passes in [1,2,3]:
 for hm in ['avg','sum']:
  for sm in ['div','none']:
   W,O,l=sim(passes,hm,sm); print(passes,hm,sm,"W",[[round(x,5) for x in r] for r in W],"O",[[round(x,5) for x in r] for r in O],"loss",round(l,6))
PY"}

