import subprocess,os,re
def evaltrain(exe,args,out):
 r=subprocess.run([exe]+args+["-output",out],capture_output=True,text=True,timeout=30)
 loss=None
 m=re.findall(r"avg.loss:\s+(\S+)",r.stderr)
 if m: loss=m[-1]
 vec=open(out+".vec").read() if os.path.exists(out+".vec") else ""
 return r.returncode,loss,vec,r.stderr
